def _is_owner_only_slash(qualified: str) -> bool:
    """`qualified` 形如 `input key press`（不含前導斜線）。"""
    return (qualified.split(" ", 1)[0] in _OWNER_ONLY_GROUPS
            or qualified in _OWNER_ONLY_SLASH)


def _role_ids(name: str) -> set[int]:
    try:
        return {int(v) for v in USER_ROLES.get(name, [])}
    except Exception:  # pylint: disable=broad-except
        return set()


def _roles_configured() -> bool:
    return bool(
        _role_ids("admin_user_ids")
        or _role_ids("operator_user_ids")
        or _role_ids("viewer_user_ids")
    )


def _user_role(user_id: int) -> str:
    if user_id == OWNER_USER_ID:
        return "admin"
    if user_id in _role_ids("admin_user_ids"):
        return "admin"
    if user_id in _role_ids("operator_user_ids"):
        return "operator"
    if user_id in _role_ids("viewer_user_ids"):
        return "viewer"
    return "none"


def _command_required_role(head: str, rest: str = "") -> str:
    del rest
    if head in _VIEWER_COMMANDS:
        return "viewer"
    if head in _ADMIN_COMMANDS:
        return "admin"
    return "operator"


def _role_allows(role: str, required: str) -> bool:
    order = {"none": 0, "viewer": 1, "operator": 2, "admin": 3}
    return order.get(role, 0) >= order.get(required, 3)


async def _check_command_permission(message: discord.Message,
                                    head: str, rest: str = "") -> bool:
    if not _roles_configured():
        return True
    required = _command_required_role(head, rest)
    role = _user_role(message.author.id)
    if _role_allows(role, required):
        return True
    # safe_reply：這個呼叫點在 dispatcher 的 try 之外，使用者若在 bot 回覆前
    # 刪掉自己那則訊息，裸 reply 會丟 50035 Unknown message 直接冒出 on_message。
    await safe_reply(
        message, f"此指令需要 `{required}` 權限；你目前是 `{role}`。")
    return False


