# ---------- help text (markdown, multi-language) ---------------------------
# Help is split into:
#   - channel-only sections (only shown to requests from CHANNEL_ID)
#   - mention sections (shown in every channel)
# Each is provided in three languages: zh-tw (default), zh-cn, en. Discord
# caps a single message at 2000 chars, so each language stores a list of
# small sections that _send_help glues into <=1900-char chunks.

DEFAULT_HELP_LANG = BOT_CONFIG["default_help_lang"]
LANG_ALIASES: dict[str, str] = {
    # Traditional Chinese
    "tw": "zh-tw", "zh-tw": "zh-tw", "zh_tw": "zh-tw", "zhtw": "zh-tw",
    "zh-hant": "zh-tw", "繁": "zh-tw", "繁體": "zh-tw", "繁中": "zh-tw",
    "trad": "zh-tw", "traditional": "zh-tw",
    # Simplified Chinese
    "cn": "zh-cn", "zh-cn": "zh-cn", "zh_cn": "zh-cn", "zhcn": "zh-cn",
    "zh-hans": "zh-cn", "简": "zh-cn", "简体": "zh-cn", "簡體": "zh-cn",
    "简中": "zh-cn", "simp": "zh-cn", "simplified": "zh-cn",
    # English
    "en": "en", "english": "en", "eng": "en", "英": "en", "英文": "en",
}


def _resolve_lang(text: str) -> str:
    if not text:
        return DEFAULT_HELP_LANG
    return LANG_ALIASES.get(text.strip().lower(), DEFAULT_HELP_LANG)


def _split_help_section(section: str, limit: int = 1900) -> list[str]:
    """把一段 help 切成不超過 `limit` 的片段。

    一般段落整段就進得去，這條路徑什麼都不做。真的過長時才逐行切；連單獨一行
    都超過上限的病態情況再硬切——「送不出去」比「切在奇怪的位置」糟得多。
    """
    if len(section) <= limit:
        return [section]
    pieces: list[str] = []
    buf = ""
    for line in section.split("\n"):
        while len(line) > limit:
            if buf:
                pieces.append(buf)
                buf = ""
            pieces.append(line[:limit])
            line = line[limit:]
        addition = line if not buf else "\n" + line
        if len(buf) + len(addition) > limit:
            pieces.append(buf)
            buf = line
        else:
            buf += addition
    if buf:
        pieces.append(buf)
    return pieces


async def _send_help(message: discord.Message, *, include_channel_only: bool,
                    lang: str = DEFAULT_HELP_LANG) -> None:
    """Send the help in markdown, broken into <=1900-char chunks."""
    pack = HELPS.get(lang) or HELPS[DEFAULT_HELP_LANG]
    sections: list[str] = []
    if include_channel_only:
        sections.extend(pack["channel"])
    sections.extend(pack["mention"])
    # ⚠️ 分塊必須也切得動**單一段落內部**。舊版只在段落之間切，所以一個超過
    # 1900 字元的段落會原封不動變成一則訊息，然後被平台以 2000 字元上限拒絕
    # （50035）。`!help` 因此會送出前幾塊之後直接失敗——三種語言都會，而且沒有
    # 任何測試守著。現在超長段落改成逐行再切。
    chunks: list[str] = []
    buf = ""
    for section in sections:
        for piece in _split_help_section(section):
            addition = piece if not buf else "\n" + piece
            if len(buf) + len(addition) > 1900:
                if buf:
                    chunks.append(buf)
                buf = piece
            else:
                buf += addition
    if buf:
        chunks.append(buf)
    first = True
    for chunk in chunks:
        if first:
            await safe_reply(message, chunk)
            first = False
        else:
            await message.channel.send(chunk)




async def cmd_help(message: discord.Message, payload: str = "") -> None:
    # `!` commands only fire in CHANNEL_ID, so this is always the full help.
    lang = _resolve_lang(payload)
    await _send_help(message, include_channel_only=True, lang=lang)


# ---------- monitoring commands ---------------------------------------------

async def cmd_tail(message: discord.Message, payload: str) -> None:
    text = payload.strip()
    try:
        n = int(text) if text else 20
    except ValueError:
        await safe_reply(message, "usage: `/log tail [N]` (default 20, max 200)")
        return
    n = max(1, min(n, 200))
    # 整份 log 丟工作執行緒讀（`/log` 這一族的判準寫在 `_webrunner_log_lines`）。
    try:
        lines = await asyncio.to_thread(_webrunner_log_lines)
    except OSError as error:
        print(f"cmd_tail read failed: {error!r}", file=sys.stderr)
        await safe_reply(message, _owner_error(
            message, error, "讀取 log 失敗，請查看主機 log。"))
        return
    if lines is None:
        await safe_reply(message, "log 檔尚不存在 — 還沒跑過？")
        return
    if not lines:
        await safe_reply(message, "log 檔是空的")
        return
    actual = min(n, len(lines))
    tail_text = "\n".join(lines[-actual:])
    # Redact BEFORE truncating so whole paths collapse to `[path]` (a boundary
    # cut can't leave a half-path fragment) — Discord-bound only; the on-disk
    # log keeps the raw content.
    tail_text = _redact_for_discord(tail_text)
    if len(tail_text) > 1800:
        tail_text = "…\n" + tail_text[-1800:]
    safe = _fence_escape(tail_text)
    await safe_reply(
        message,
        f"**log** — last {actual} of {len(lines)} lines:\n"
        f"```\n{safe}\n```"
    )


# Lines worth surfacing for !errors — webrunner's own WARN/CRITICAL prints,
# Python tracebacks, selenium fill-verify mismatches, and the Chrome OOM /
# crash interstitial markers. Case-insensitive.
_LOG_ERROR_RE = re.compile(
    r"WARN|ERROR|CRITICAL|Traceback|Exception|mismatch|Aw, *Snap|"
    r"Out of Memory|SessionNotCreated|ReadTimeout",
    re.IGNORECASE,
)
LOG_GREP_MAX_MATCHES = 40


def _webrunner_log_lines() -> list[str] | None:
    """整份 log 切成行；log 還不存在回 None，存在卻讀不出來往外丟 `OSError`。

    **`/log tail`、`/log grep`、`/log errors` 與兩個計數（`_recent_log_error_count`、
    `_health_log_scan`）共用這一支，而且都丟 `asyncio.to_thread` 跑**（2026-09-19）。這個檔可以丟執行緒，理由跟 `_recent_log_error_count` 一樣
    （寫在那支的 docstring）：同一個行程裡唯一會對它做 `os.replace` 的是
    `_rotate_webrunner_log`，改名失敗本來就退回「複製＋原地截斷」，兩步對開著的讀者
    都成功（`test_a_reader_holding_the_log_does_not_break_the_rotation`）。判準本身
    ——bot 自己在迴圈上 `os.replace` 的檔連 `stat` 都留在迴圈上，其餘丟執行緒——寫在
    `cmd_doctor` 開頭。

    不先問 `exists()`：輪替正好把檔案改名走的那一瞬間，先問再讀會把一個正常狀態報成
    「讀不出來」。用 `FileNotFoundError` 分辨「還沒跑過」。
    """
    try:
        text = WEBRUNNER_LOG.read_text(encoding="utf-8", errors="replace")
    except FileNotFoundError:
        return None
    return text.splitlines()


def _read_log_lines() -> tuple[list[str] | None, str]:
    """Return (lines, "") or (None, error_message_for_reply).

    同步整份讀檔：async 呼叫端要走 `_scan_log` 丟執行緒，不要在迴圈上直接叫。
    """
    try:
        lines = _webrunner_log_lines()
    except OSError as error:
        print(f"_read_log_lines read failed: {error!r}", file=sys.stderr)
        return None, "讀取 log 失敗，請查看主機 log。"
    if lines is None:
        return None, "log 檔尚不存在 — 還沒跑過？"
    return lines, ""


def _scan_log(match) -> tuple[list[tuple[int, str]] | None, int, str]:
    """讀 log 並挑出 `match(行)` 為真的行：回 `(命中, 總行數, "")`；讀不到回
    `(None, 0, 給使用者的那一句)`。

    **讀檔與逐行比對一起在工作執行緒上跑**，比對不是零成本：2026-09-19 實測 8,283 行
    （約 700 KB）時 `_LOG_ERROR_RE` 過一遍約 50 ms，比讀檔本身（約 4 ms）大十幾倍，
    而監督者那條路的修剪門檻是 8 MB，行數還能再多十倍以上。比對在執行緒上仍然拿著
    GIL，但事件迴圈那條執行緒要 GIL 時，直譯器最多隔一個切換間隔（預設 5 ms）就會
    讓出，心跳不必等整段跑完。
    """
    lines, err = _read_log_lines()
    if lines is None:
        return None, 0, err
    return [(i, ln) for i, ln in enumerate(lines, 1) if match(ln)], len(lines), ""


# 「最近這麼多行裡有幾行像錯誤」——`/sys doctor`、健康報告、失敗摘要三處共用同一個
# 算法，所以只寫一次。
RECENT_LOG_SCAN_LINES = 200


def _recent_log_error_count(tail: int = RECENT_LOG_SCAN_LINES) -> int | None:
    """log 最後 `tail` 行裡符合 `_LOG_ERROR_RE` 的行數；log 還不存在時回 None。

    讀得到檔案卻讀不出來時**往外丟** `OSError`，不自己吞：三個呼叫端對「查不成」
    的說法本來就不一樣（doctor 要講出來、健康報告寫 `?`、失敗摘要略過），由它們
    各自決定。檔案不存在則是「還沒跑過」，不是查不成——用 `FileNotFoundError`
    分辨而不是先問 `exists()`：輪替正好把檔案改名走的那一瞬間，先問再讀會把一個
    正常狀態報成「讀不出來」。

    這支會把整份讀進來（2026-09-19 實測約 670 KB，讀加掃約 3 ms），所以 async 呼叫
    端要丟 `asyncio.to_thread`。丟執行緒是安全的，但理由要講清楚，因為同一個 bot
    有別的檔**不能**這樣丟（見 `cmd_doctor` 開頭的註解）：這個行程裡唯一會對這個檔
    做 `os.replace` 的是 `_rotate_webrunner_log`，而它改名失敗時本來就會退回「複製
    ＋原地截斷」——兩步在檔案被別的 handle 開著讀時實測都會成功
    （`test_a_reader_holding_the_log_does_not_break_the_rotation`），而且那是它的
    常態路徑：這個檔平常就被監督者與背景程式握著。
    """
    lines = _webrunner_log_lines()
    if lines is None:
        return None
    return sum(1 for ln in lines[-tail:] if _LOG_ERROR_RE.search(ln))


async def _reply_log_matches(message: discord.Message,
                             matches: list[tuple[int, str]],
                             total: int, label: str) -> None:
    if not matches:
        await safe_reply(
            message,
            f"no lines matching {label} in {total} log line(s)"
        )
        return
    shown = matches[-LOG_GREP_MAX_MATCHES:]  # most recent matches
    body = "\n".join(f"{i}: {ln}" for i, ln in shown)
    # Redact RAW log lines before they reach Discord (paths / brand / webrunner
    # noun → neutral tokens). Done before truncation so paths collapse whole.
    body = _redact_for_discord(body)
    if len(body) > 1800:
        body = "…\n" + body[-1800:]
    safe = _fence_escape(body)
    more = (f" (showing last {len(shown)})" if len(matches) > len(shown) else "")
    await safe_reply(
        message,
        f"**log** — {len(matches)} match(es) for {label}"
        f"{more}:\n```\n{safe}\n```"
    )


async def cmd_log_grep(message: discord.Message, payload: str) -> None:
    """Case-insensitive substring search over webrunner.log, newest matches
    first-capped. Complements !tail for finding a specific line in a long
    log without paging through it."""
    needle = payload.strip()
    if not needle:
        await safe_reply(message, "usage: `/log grep <substring>` (case-insensitive)")
        return
    low = needle.lower()
    # 讀檔加逐行比對一起丟執行緒（見 `_scan_log`）。
    matches, total, err = await asyncio.to_thread(
        _scan_log, lambda ln: low in ln.lower())
    if matches is None:
        await safe_reply(message, err)
        return
    await _reply_log_matches(message, matches, total, f"`{needle}`")


async def cmd_errors(message: discord.Message) -> None:
    """Show recent WARN / ERROR / CRITICAL / traceback / mismatch / Chrome-OOM
    lines from webrunner.log — a one-shot health scan without paging !tail."""
    # 讀檔加逐行比對一起丟執行緒：這一支的正規表示式是 `/log` 裡最貴的一段（見 `_scan_log`）。
    matches, total, err = await asyncio.to_thread(_scan_log, _LOG_ERROR_RE.search)
    if matches is None:
        await safe_reply(message, err)
        return
    await _reply_log_matches(message, matches, total, "errors/warnings")


async def cmd_queue(message: discord.Message) -> None:
    p1 = read_todo_entries(TODO_PROMPT_FILE)
    c1 = read_todo_entries(TODO_FILE_1)
    c2 = read_todo_entries(TODO_FILE_2)
    u1 = read_todo_entries(TODO_UNDESIRED_FILE)
    raw_pairs = max(len(p1), len(c1), len(c2), len(u1))
    eff_pairs, end_idx = _effective_pair_count(p1, c1, c2, u1)
    color = 0x57F287 if eff_pairs > 0 else 0xED4245
    embed = discord.Embed(title="📋 Todo queue", color=color)
    embed.add_field(name=_list_label(TODO_PROMPT_FILE, message), value=f"`{len(p1)}`", inline=True)
    embed.add_field(name=_list_label(TODO_FILE_1, message), value=f"`{len(c1)}`", inline=True)
    embed.add_field(name=_list_label(TODO_FILE_2, message), value=f"`{len(c2)}`", inline=True)
    embed.add_field(name=_list_label(TODO_UNDESIRED_FILE, message), value=f"`{len(u1)}`", inline=True)
    if end_idx is not None:
        embed.add_field(
            name="pairs (until `end`)",
            value=f"**{eff_pairs}** / {raw_pairs}",
            inline=False,
        )
        embed.add_field(
            name="⏹ end marker",
            value=f"主提示詞佇列第 #{end_idx + 1} 筆 — run stops there",
            inline=False,
        )
    else:
        embed.add_field(name="pairs (max)", value=f"**{raw_pairs}**", inline=False)
    if eff_pairs == 0:
        embed.set_footer(text="queue empty — 背景程式會用 fallback / no-op")
    await safe_reply(message, embed=embed)


async def cmd_eta(message: discord.Message) -> None:
    p1 = read_todo_entries(TODO_PROMPT_FILE)
    c1 = read_todo_entries(TODO_FILE_1)
    c2 = read_todo_entries(TODO_FILE_2)
    u1 = read_todo_entries(TODO_UNDESIRED_FILE)
    pairs, end_idx = _effective_pair_count(p1, c1, c2, u1)
    if pairs == 0:
        if end_idx == 0:
            await safe_reply(
                message,
                "主提示詞佇列第一筆就是 `end` — run stops "
                "immediately; nothing to estimate. `/todo prompt unend` to resume."
            )
        else:
            await safe_reply(message, "queue is empty — nothing to estimate")
        return
    batch_cfg = load_batch_config()
    imgs_per_pair = batch_cfg["images_per_character"]
    work_hours = batch_cfg["schedule_limit_hours"]
    rest_hours = batch_cfg["rest_hours"]
    spi, measured, basis, verified = _seconds_per_image()
    secs_per_pair = imgs_per_pair * spi
    total_work = pairs * secs_per_pair
    work_window = work_hours * 3600
    rest_window = rest_hours * 3600
    full_cycles = int(total_work // work_window)
    total_wall = total_work + full_cycles * rest_window
    # `full_cycles` 只數**未來**會發生的休息。如果此刻正在休息，剩下的那一段是
    # 已經確定要等、但一張圖都不會產的時間——不加進去，ETA 就會少報最多
    # `rest_hours`（預設 6 小時）。
    resting_until = _scheduled_rest_until()
    rest_left = max(0.0, resting_until - time.time()) if resting_until else 0.0
    total_wall += rest_left
    eta_ts = time.time() + total_wall
    eta_str = time.strftime("%Y-%m-%d %H:%M", time.localtime(eta_ts))
    embed = discord.Embed(title="⏳ ETA estimate", color=0x5865F2)
    embed.add_field(name="pairs", value=str(pairs), inline=True)
    embed.add_field(
        name="per pair",
        value=f"~{secs_per_pair / 60:.0f} min ({imgs_per_pair} × ~{spi:.0f}s)",
        inline=True,
    )
    embed.add_field(name="raw work", value=_format_duration(int(total_work)), inline=True)
    # 現在正在休息的那一段也要顯示出來，否則欄位加不回總時間（raw work +
    # rest periods != total wall），使用者會以為總時間算錯了。
    rest_value = f"{full_cycles} × {rest_hours}h"
    if rest_left > 0:
        rest_value += f" + {_format_duration_short(rest_left)} (resting now)"
    embed.add_field(
        name="rest periods",
        value=rest_value,
        inline=True,
    )
    embed.add_field(name="total wall time", value=_format_duration(int(total_wall)), inline=True)
    embed.add_field(name="projected finish", value=eta_str, inline=True)
    # 據實說明數字的來源。原本不論取樣範圍一律寫「measured from recent
    # runs」，而實際上它平均了六天的歷史——包含速率完全不同的舊時期。
    src = {
        "window": (f"measured from the last "
                   f"{ETA_SAMPLE_WINDOW_SEC // 3600}h of finished items"),
        # 視窗只蓋到週期的一個相位時會往回補到一個完整週期，這時候寫「最近 24
        # 小時」就是假的——樣本本來就刻意伸出了視窗外。
        "cycle": ("measured across one full work/rest cycle (an item right "
                  "after a rest runs faster, so a single one is not "
                  "representative)"),
        "recent": (f"measured from the last {ETA_FALLBACK_SAMPLES} finished "
                   f"items (none in the last "
                   f"{ETA_SAMPLE_WINDOW_SEC // 3600}h — may be stale)"),
        "default": (f"default ~{ETA_SECONDS_PER_IMAGE}s/image "
                    f"(no run history yet)"),
    }[basis if measured else "default"]
    footer = f"{src}; retries can push this higher."
    if measured and not verified:
        # 「查不到」不可以靜默地退回那個已知會偏樂觀的答案——見
        # `_images_this_run` 第二個回傳值的說明。
        footer += (" Some samples could not be checked against a restart, "
                   "so this may be optimistic.")
    if end_idx is not None:
        footer += f" Capped by `end` marker at entry #{end_idx + 1}."
    embed.set_footer(text=footer)
    await safe_reply(message, embed=embed)


# ---------- batch_config view / edit (!config, !config_set) -----------------
# The webrunner hot-reloads batch_config.json at the start of every character,
# so a !config_set takes effect on the NEXT character without restarting the
# run (exception: debug_screenshots is read once at webrunner import, so it
# needs !stop + !run). Parsers below mirror _batch_config's coercion rules so
# a value accepted here survives the loader's defensive re-coerce on reload.
# The consecutive-failure ALERT threshold (webrunner constant, 5) is the floor
# for consecutive_fail_abort — it MUST stay above the alert (CLAUDE.md).
_CONSECUTIVE_FAIL_ALERT = 5


def _fmt_num(x) -> str:
    """Render a number without a trailing `.0` for whole values."""
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    return str(x)


def _parse_cfg_int(s: str, min_value: int):
    try:
        v = int(s)
    except ValueError:
        return None, f"must be an integer ≥ {min_value}"
    if v < min_value:
        return None, f"must be ≥ {min_value}"
    # 最後一道直接問載入器自己的規則，不在這裡另抄一份上限。`int()` 收得下幾千位數
    # 的字串，而載入器只認轉得成有限 float 的整數（`_is_finite_number`）——309 位數
    # 的 `9…9` 在這裡原本會回報「set ok」、真的寫進檔案，之後每一次重新載入都靜靜
    # 退回預設。判定用 sentinel 比 `is`，理由見 `_batch_config._REJECTED`。
    if _batch_coerce_int(v, _BATCH_REJECTED,
                         min_value=min_value) is _BATCH_REJECTED:
        return None, "is out of the accepted range"
    return v, ""


def _parse_cfg_num(s: str):
    try:
        v = float(s)
    except ValueError:
        return None, "must be a positive number"
    if not math.isfinite(v):
        # inf / nan 會通過 v <= 0 檢查，但 json.dumps 預設會寫出裸的
        # Infinity / NaN（非標準 JSON），且 inf 等於讓批次永不進入休息週期。
        return None, "must be a finite number"
    if v <= 0:
        return None, "must be > 0"
    return (int(v) if v.is_integer() else v), ""


def _parse_cfg_ratio(s: str):
    # Mirror `_batch_config._coerce_ratio` exactly (0 < value ≤ 1): a value the
    # bot accepts but the loader rejects would silently revert to default on
    # the next reload, showing a "success" that doesn't stick.
    try:
        v = float(s)
    except ValueError:
        return None, "must be a fraction in (0, 1], e.g. `0.9`"
    if not 0 < v <= 1:
        return None, "must be > 0 and ≤ 1 (e.g. `0.9` = 90%)"
    return v, ""


def _parse_cfg_bool(s: str):
    low = s.strip().lower()
    if low in ("true", "1", "on", "yes", "y"):
        return True, ""
    if low in ("false", "0", "off", "no", "n"):
        return False, ""
    return None, "must be true / false"


# `/config set` 區間值裡的一個數字。原本是 `re.split(r"[,\s\-]+", …)`：為了支援
# `3-5` 這種寫法把 `-` 一律當分隔符，副作用是負號被吃掉——`-3,5` 存成 3–5、`0,-3`
# 存成 0–3、`3--5` 存成 3–5，下面那道 `lo < 0` 永遠等不到負數；`1e-3,5` 反而被拆成
# 三段而擋掉。現在 `-` 依位置決定身分：
# * 前面是字串開頭、空白、逗號或另一個 `-`，而且後面緊接著數字本體 → **正負號**，
#   屬於後面那個數字（`-3,5`、`0,-3`、`3 -5`、`3--5` 的第二個）；
# * 緊跟在 e/E 後面 → **指數的負號**，留在數字裡（`1e-3`）；
# * 其餘（`3-5`、`3 - 5`、`3- 5`）→ 兩個數字之間的**區間分隔符**，跟逗號與空白一樣
#   不進任何數字。
# en dash `–`（U+2013）跟 `-` 走同一套位置規則，差別只有它不會出現在指數裡——它
# 存在的理由是 `_fmt_cfg_value` 就是用它顯示區間（`/config show` 印 `3–5`），使用者
# 照抄回來必須設得進去。落在正負號位置的 `–`（`–3,5`、`3 –5`）照樣被收進數字裡，
# 於是 `float()` 解不開而整筆擋下：打在負號位置的 en dash 意思不明，而負數絕不能
# 靜靜變成正數。
# 全形逗號（`20，30`）維持原本的行為：不是分隔符，整串當一個數字而被擋下。
_CFG_PAIR_NUMBER_RE = re.compile(r"(?:(?<![^\s,\-–])[-–])?(?:[^\s,\-–]|(?<=[eE])-)+")
# 兩個數字**外面**只准逗號與空白（`,3,5`、`3,5,` 是原本就收的寬容寫法）；**中間**是
# 逗號／空白，或恰好一條 `-`／`–`。沒有夾在兩個數字之間的破折號（`3,5–`、`- 3,5`）
# 不可以被當成分隔符默默丟掉，整筆擋下。
_CFG_PAIR_OUTER_GAP_RE = re.compile(r"[\s,]*")
_CFG_PAIR_MIDDLE_GAP_RE = re.compile(r"[\s,]+|\s*[-–]\s*")


def _parse_cfg_pair(s: str):
    text = s.strip()
    found = list(_CFG_PAIR_NUMBER_RE.finditer(text))
    if len(found) != 2:
        return None, "need two numbers, e.g. `20,30`"
    first, second = found
    if not (_CFG_PAIR_OUTER_GAP_RE.fullmatch(text[:first.start()])
            and _CFG_PAIR_MIDDLE_GAP_RE.fullmatch(text[first.end():second.start()])
            and _CFG_PAIR_OUTER_GAP_RE.fullmatch(text[second.end():])):
        return None, "a dash (- or –) is only allowed between the two numbers"
    parts = [first.group(), second.group()]
    try:
        lo, hi = float(parts[0]), float(parts[1])
    except ValueError:
        return None, "both values must be numbers"
    if not (math.isfinite(lo) and math.isfinite(hi)):
        # 與 `_parse_cfg_num` 同樣的理由，只是這裡的後果更差：`float("inf")` 與
        # `1e400` 都通得過 `lo > hi`（`inf > inf` 為假），而 `nan` 連 `lo < 0` 都
        # 是假的。放行的話 `json.dumps` 會寫出裸的 `Infinity` / `NaN`（非法 JSON），
        # 而且 `random.uniform(inf, inf)` 回 nan → `time.sleep(nan)` 直接
        # `ValueError`，角色迴圈在第一次圖間等待就炸。nan 更糟：載入器會把它退回
        # 預設，於是指令回報「設定成功」但值根本沒有生效。
        return None, "must be finite numbers"
    if lo < 0 or lo > hi:
        return None, "need 0 ≤ lo ≤ hi"
    norm = [int(v) if v.is_integer() else v for v in (lo, hi)]
    return norm, ""


# key → parser(str) -> (value, error_str). Only these keys are settable.
_BATCH_SETTERS: dict = {
    "images_per_character": lambda s: _parse_cfg_int(s, 1),
    "inter_image_delay_sec": _parse_cfg_pair,
    "schedule_limit_hours": _parse_cfg_num,
    "rest_hours": _parse_cfg_num,
    "generate_max_retries": lambda s: _parse_cfg_int(s, 1),
    "generate_retry_delay_sec": _parse_cfg_pair,
    "download_max_retries": lambda s: _parse_cfg_int(s, 1),
    "consecutive_fail_abort": lambda s: _parse_cfg_int(s, _CONSECUTIVE_FAIL_ALERT + 1),
    "restart_chrome_every_n_characters": lambda s: _parse_cfg_int(s, 0),
    "min_save_ratio": _parse_cfg_ratio,
    "debug_screenshots": _parse_cfg_bool,
}


def _fmt_cfg_value(val) -> str:
    if isinstance(val, bool):
        return str(val).lower()
    if isinstance(val, (list, tuple)):
        return f"{_fmt_num(val[0])}–{_fmt_num(val[1])}"
    return _fmt_num(val)


async def cmd_config(message: discord.Message) -> None:
    """Show the effective batch_config.json (defaults-merged), flagging which
    keys are using the built-in default vs an on-disk override."""
    cfg = load_batch_config()
    raw = read_raw_batch_config()
    lines = []
    for key in _BATCH_SETTERS:
        shown = _fmt_cfg_value(cfg[key])
        origin = "" if key in raw else "  (default)"
        lines.append(f"{key:<34} {shown}{origin}")
    body = "\n".join(lines)
    embed = discord.Embed(
        title="⚙️ batch 設定",
        description=f"```\n{_fence_escape(body)}\n```",
        color=0x5865F2,
    )
    embed.set_footer(
        text="/config set <key> <value> to change — applies on the NEXT "
             "character (debug_screenshots needs /stop + /run)"
    )
    await safe_reply(message, embed=embed)


async def cmd_config_set(message: discord.Message, payload: str) -> None:
    parts = payload.strip().split(None, 1)
    if len(parts) < 2:
        keys = ", ".join(f"`{k}`" for k in _BATCH_SETTERS)
        await safe_reply(
            message,
            f"usage: `/config set <key> <value>`\nsettable keys: {keys}"
        )
        return
    key, raw_val = parts[0], parts[1].strip()
    if key not in _BATCH_SETTERS:
        await safe_reply(
            message,
            f"unknown key `{key}` — `/config show` lists the settable keys"
        )
        return
    value, err = _BATCH_SETTERS[key](raw_val)
    if err:
        extra = ""
        if key == "consecutive_fail_abort":
            extra = (f" (must stay above the consecutive-failure ALERT "
                     f"threshold of {_CONSECUTIVE_FAIL_ALERT})")
        await safe_reply(message, f"invalid value for `{key}`: {err}{extra}")
        return
    old = load_batch_config().get(key)
    try:
        new_cfg = save_batch_config({key: value})
    except (OSError, ValueError) as error:
        # ValueError ＝ `allow_nan=False` 攔下了 inf/nan（上面的 parser 應該已經擋掉，
        # 這是第二層）。兩種都不該讓使用者看到原始訊息。
        # repr(OSError) embeds the absolute config path — stderr only.
        print(f"cmd_config_set save failed: {error!r}", file=sys.stderr)
        await safe_reply(message, _owner_error(
            message, error, "寫入設定檔失敗，請查看 log。"))
        return
    applied = new_cfg.get(key)
    if key == "debug_screenshots":
        note = "\n⚠️ 此項在程式啟動時讀取一次 — 需 `/stop` + `/run` 才生效"
    else:
        note = "\napplies on the **next** character iteration"
    await safe_reply(
        message,
        f"set `{key}`: `{_fmt_cfg_value(old)}` → `{_fmt_cfg_value(applied)}`{note}"
    )


async def cmd_config_reset(message: discord.Message, payload: str) -> None:
    """Remove an override so a key reverts to its built-in default.
    `/config reset <key>` for one key, or `/config reset all` to clear every
    override (delete all overrides, back to stock defaults)."""
    arg = payload.strip()
    if not arg:
        keys = ", ".join(f"`{k}`" for k in _BATCH_SETTERS)
        await safe_reply(
            message,
            f"usage: `/config reset <key>` or `/config reset all`\nkeys: {keys}"
        )
        return
    if arg.lower() == "all":
        targets = list(_BATCH_SETTERS)
    elif arg in _BATCH_SETTERS:
        targets = [arg]
    else:
        await safe_reply(
            message,
            f"unknown key `{arg}` — `/config show` lists the settable keys "
            f"(or `all`)"
        )
        return
    try:
        new_cfg, removed = reset_batch_config_keys(targets)
    except OSError as error:
        print(f"cmd_config_reset save failed: {error!r}", file=sys.stderr)
        await safe_reply(message, _owner_error(
            message, error, "寫入設定檔失敗，請查看 log。"))
        return
    if not removed:
        scope = "any key" if arg.lower() == "all" else f"`{arg}`"
        await safe_reply(
            message,
            f"{scope} already at default (no on-disk override to remove)"
        )
        return
    if len(removed) == 1:
        k = removed[0]
        await safe_reply(
            message,
            f"reset `{k}` to default `{_fmt_cfg_value(new_cfg[k])}` — "
            f"applies on the **next** character"
        )
    else:
        await safe_reply(
            message,
            f"reset {len(removed)} override(s) to defaults "
            f"({', '.join(f'`{k}`' for k in removed)}) — applies on the "
            f"**next** character"
        )


async def cmd_config_reload(message: discord.Message) -> None:
    """Reload runtime-safe bot_config fields without restarting Discord."""
    if message.author.id != OWNER_USER_ID:
        await safe_reply(message, "此指令僅限擁有者使用。")
        return
    global BOT_CONFIG, USER_ROLES, DAILY_HEALTH_REPORT, DASHBOARD_CONFIG
    global MIN_FREE_DISK_GB, ALERT_USER_ID, GUI_LAUNCH_WHITELIST, GUI_LAUNCH_ALIASES
    global DOROSSI_MODEL_CHECK
    old_roles = USER_ROLES
    BOT_CONFIG = load_bot_config()
    USER_ROLES = BOT_CONFIG["user_roles"]
    DAILY_HEALTH_REPORT = BOT_CONFIG["daily_health_report"]
    DASHBOARD_CONFIG = BOT_CONFIG["dashboard"]
    DOROSSI_MODEL_CHECK = BOT_CONFIG["dorossi_model_check"]
    MIN_FREE_DISK_GB = BOT_CONFIG["min_free_disk_gb"]
    ALERT_USER_ID = BOT_CONFIG["alert_user_id"]
    GUI_LAUNCH_WHITELIST = BOT_CONFIG["gui_control"]["launch_whitelist"]
    GUI_LAUNCH_ALIASES = BOT_CONFIG["gui_control"]["launch_aliases"]
    changed = old_roles != USER_ROLES
    await safe_reply(
        message,
        "已重載 runtime-safe 設定：roles、alert、disk、launch、"
        f"daily report、dashboard。roles changed=`{str(changed).lower()}`。"
    )


def _gather_output_images() -> list[tuple[float, Path]]:
    """Return (mtime, path) for every visible output image, newest unsorted."""
    if not OUTPUT_ROOT.exists():
        return []
    results: list[tuple[float, Path]] = []
    for d in OUTPUT_ROOT.iterdir():
        if not d.is_dir():
            continue
        try:
            entries = list(d.iterdir())
        except OSError:
            continue
        for p in entries:
            if not p.is_file():
                continue
            if p.suffix.lower() not in (".png", ".jpg", ".jpeg", ".webp"):
                continue
            try:
                results.append((p.stat().st_mtime, p))
            except OSError:
                pass
    return results


# 對話平台的**預設**單檔上傳上限。平台官方更新紀錄 2026-09-03：使用者、bot、webhook
# 與互動回應的預設上限由 10 MiB 調到 20 MiB。這個值原本寫 8 MB，比平台落後兩版——
# 於是 8–20 MB 的圖明明傳得上去，指令卻說「超過上限」。
#
# 它只是**退路**：伺服器有回報上限時一律以回報的為準，見 `_upload_limit_bytes`。
DISCORD_FILE_LIMIT = 20 * 1024 * 1024


def _positive_int(value) -> int | None:
    """正整數才收（`bool` 是 `int` 的子類，要排除），其他一律 None。"""
    if isinstance(value, int) and not isinstance(value, bool) and value > 0:
        return value
    return None


def _upload_limit_bytes(source) -> int:
    """這一次上傳適用的單檔上限（位元組）。`source` 是訊息、斜線指令的代理物件或頻道。

    優先序，**所有會上傳檔案的地方都走這一支**：
    1. 斜線指令（`_InteractionMessageProxy`）：`Interaction.filesize_limit`——那是互動
       payload 的 `attachment_size_limit`，伺服器算好的、已經含加成等級，照單全收。
    2. 伺服器裡的訊息或頻道：`max(DISCORD_FILE_LIMIT, guild.filesize_limit)`。要取 max
       是因為函式庫算 `Guild.filesize_limit` 時，沒有加成的伺服器用的是它自己寫死的
       `utils.DEFAULT_FILE_SIZE_LIMIT_BYTES`（2.7.1 是 10 MiB），比平台現在的預設舊；
       加成等級較高時它給的數字較大，就用它的。
    3. 其他（私訊、取不到伺服器）：`DISCORD_FILE_LIMIT`。

    ⚠️ 一般的 `discord.Message` 也有 `_interaction` 屬性，但那是 `MessageInteraction`
    （沒有 `filesize_limit`），所以會照常落到第 2 步——判斷靠的是「有沒有伺服器回報的
    數字」，不是「有沒有那個屬性」。
    """
    interaction = getattr(source, "_interaction", None)
    reported = _positive_int(getattr(interaction, "filesize_limit", None))
    if reported is not None:
        return reported
    guild = getattr(source, "guild", None)
    guild_limit = _positive_int(getattr(guild, "filesize_limit", None))
    if guild_limit is not None:
        return max(DISCORD_FILE_LIMIT, guild_limit)
    return DISCORD_FILE_LIMIT


def _mb_text(limit: int) -> str:
    """上限的顯示字串（`20 MB`）。訊息裡的數字一律從實際採用的上限算，不寫死。"""
    return f"{limit / 1024 / 1024:g} MB"


async def cmd_latest(message: discord.Message, payload: str) -> None:
    text = payload.strip()
    try:
        n = int(text) if text else 1
    except ValueError:
        await safe_reply(message, "usage: `/latest [N]` (default 1, max 5)")
        return
    n = max(1, min(n, 5))
    images = _gather_output_images()
    if not images:
        await safe_reply(message, "產出資料夾裡還沒有任何圖片")
        return
    images.sort(key=lambda x: x[0], reverse=True)
    picked = images[:n]
    files: list[discord.File] = []
    paths_sent: list[Path] = []
    skipped: list[str] = []
    summary_rows: list[str] = []
    limit = _upload_limit_bytes(message)
    for mtime, p in picked:
        size = p.stat().st_size
        if size > limit:
            skipped.append(f"`{p.name}` ({size / 1024 / 1024:.1f} MB > "
                           f"{_mb_text(limit)} cap)")
            continue
        files.append(discord.File(str(p), filename=p.name))
        paths_sent.append(p)
        when = time.strftime("%H:%M:%S", time.localtime(mtime))
        summary_rows.append(f"`{p.parent.name}/{p.name}` ({when})")
    if not files:
        await safe_reply(message, "最新圖片都超過上傳大小上限")
        return
    parts = [f"latest {len(files)} of {len(picked)}:"]
    parts.extend(summary_rows)
    if skipped:
        parts.append("skipped (too large): " + ", ".join(skipped))
    sent = await safe_reply(message, "\n".join(parts), files=files)
    if sent is not None:
        _remember_image_msg(sent.id, paths_sent)


def _progress_bar(current: int, total: int, width: int = 20) -> str:
    if total <= 0:
        return "[" + "?" * width + "]"
    filled = min(int(width * current / total), width)
    return "[" + "█" * filled + "░" * (width - filled) + "]"


async def cmd_progress(message: discord.Message) -> None:
    if not OUTPUT_ROOT.exists():
        await safe_reply(message, "產出資料夾還不存在 — 目前沒有任何圖片")
        return
    dirs = sorted([d for d in OUTPUT_ROOT.iterdir() if d.is_dir()])
    if not dirs:
        await safe_reply(message, "產出資料夾裡還沒有任何角色資料夾")
        return
    rows: list[str] = []
    total_done = 0
    total_target = 0
    # Read from shared batch_config.json — drift-free with what webrunner
    # actually generates per character.
    target = load_batch_config()["images_per_character"]
    for d in dirs:
        try:
            count = sum(
                1 for p in d.iterdir()
                if p.is_file() and p.suffix.lower() in (".png", ".jpg", ".jpeg", ".webp")
            )
        except OSError:
            count = 0
        total_done += count
        total_target += target
        bar = _progress_bar(count, target)
        pct = (count / target * 100) if target else 0
        name = d.name if len(d.name) <= 30 else d.name[:27] + "…"
        rows.append(f"{name:<30}  {bar} {count:>3}/{target}  {pct:5.1f}%")
    body = "\n".join(rows)
    if len(body) > 1700:
        body = body[:1700] + "\n… (truncated)"
    overall = _progress_bar(total_done, total_target, width=30)
    overall_pct = (total_done / total_target * 100) if total_target else 0
    if overall_pct >= 100:
        color = 0x57F287
    elif overall_pct >= 50:
        color = 0xFEE75C
    else:
        color = 0x5865F2
    embed = discord.Embed(
        title=f"📊 progress (target {target}/character)",
        description=f"```\n{_fence_escape(body)}\n```",
        color=color,
    )
    embed.add_field(
        name="overall",
        value=f"`{overall}` **{total_done}/{total_target}** ({overall_pct:.1f}%)",
        inline=False,
    )
    await safe_reply(message, embed=embed)


_CODE_FENCE = "```"


def _fence_escape(text: str) -> str:
    """Make `text` safe to drop inside a ``` code fence.

    內容自己的 ``` 會提前關掉外面那個區塊，後面的內容就從程式碼區塊漏成一般訊息。
    換成外觀相近的替身字元。把不受控的內容（佇列項目、指令輸出、錄下來的按鍵）
    包進 ``` 的送出點一律經過這裡，`test_bot_helpers` 會掃每一個包裝點。"""
    return text.replace(_CODE_FENCE, "ʼʼʼ")


def _fence_preview(text: str, limit: int = 120) -> str:
    """Truncate `text` and make it safe to drop inside a ``` code fence.

    佇列項目可以是多行、也可以合法地含有 ``` —— 不跳脫的話 fence 會被提前
    關掉，後面的內容就從程式碼區塊漏成一般訊息。"""
    out = text if len(text) <= limit else text[:limit] + "…"
    return _fence_escape(out)


def _is_unsafe_folder_name(name: str) -> bool:
    """True if `name` must not be joined onto a base directory.

    `Path(base) / name` does NOT keep you inside `base`: on Windows a
    drive-anchored value replaces the base entirely, and `..` walks out.
    Every command that joins user input onto `OUTPUT_ROOT` / `DEBUG_DIR`
    must go through this.

    **這個檢查原本漏掉了它自己 docstring 舉的那個例子的無斜線版本。**
    舊版是 ``"/" in name or "\\" in name or ".." in name``，而 docstring 舉的例子
    是 ``'C:/Windows'``——那個字串**剛好帶斜線**，所以被擋下來了。但錨定到磁碟機
    靠的是冒號不是斜線，於是這四個一路通過（2026-08-30 在本機實測）：

    | 輸入 | `OUTPUT_ROOT / 輸入` | 舊版判定 |
    |---|---|---|
    | ``C:`` | ``C:`` | 安全 ✗ |
    | ``C:Windows`` | ``C:Windows`` | 安全 ✗ |
    | ``c:`` | ``c:`` | 安全 ✗ |
    | ``C:$MFT`` | ``C:$MFT`` | 安全 ✗ |

    後果不是理論的：`/out sample <資料夾>` 會把命中的圖片**上傳到頻道**，而
    `out` / `debug` 都不在 `_OWNER_ONLY_GROUPS` 裡，角色閘門在三份 `user_roles`
    都空的預設狀態下等於不存在。也就是任何能在指定頻道發言的人都做得到。
    （`D:` 不會逃出去——與 base 同一個磁碟機時，pathlib 把它當成該磁碟機的
    相對路徑，仍然落在目前工作目錄底下。逃得掉的是**別的**磁碟機。）

    現在改成「必須是單一層的相對路徑元件」這個**白名單**判準，而不是列舉危險
    字元。字元黑名單的問題正是上面那張表：少列一個就破功，而且破功時完全無聲。

    用 `PureWindowsPath` 而不是 `Path` 是刻意的：`Path` 在 POSIX 上是
    `PosixPath`，不認得 ``C:`` 是磁碟機，於是同一支測試在 Linux 上會綠、在
    Windows 上才紅。這裡要的判定與平台無關——本專案只跑 Windows。

    ⚠️ **這段原本接著寫「而更嚴格永遠不會讓合法的角色資料夾名被擋掉
    （`character_folder_name` 已經把 ``\\/:*?"<>|`` 全部換成底線）」——那個
    理由是錯的，而且結論在 2026-09-10 之前也是假的。** 字元替換管的是那七個
    字元，管不到點：當時 `character_folder_name('..')` 就是 ``'..'``、
    `character_folder_name('../../Windows')` 就是 ``'.._.._Windows'``，兩個都
    會被下面那句子字串 ``".." in name`` 判成不安全——也就是 **bot 打不開一個
    webrunner 自己建得出來的資料夾**（`/out sample` 對那個角色直接失敗）。

    今天結論是真的了，但**理由在對面**：`_webrunner_shared.character_folder_name`
    已經改成「先做原本的字元替換，再用 `_is_safe_folder_component` 做白名單
    斷言（不含 ``..``、剛好一層、沒有保留裝置名、沒有控制字元），不合格退回
    ``"character"``」。所以它的值域被保證是這支守衛會放行的形狀——實測 200k
    組對抗性輸入、18,272 個相異輸出，這支一個都沒擋。
    **這是兩個模組之間的耦合，不是本地性質**：哪天有人放寬那支的白名單斷言，
    這裡就會重新開始擋掉合法的角色名，而症狀一樣是安靜的（只有 `/out sample`
    對某個角色失敗）。
    """
    if not name:
        # 空字串是「沒給參數」，由呼叫端自己決定意義（`cmd_debug_show` 用它
        # 列出可用的檔案）。不是路徑，就不是路徑問題。
        return False
    if "/" in name or "\\" in name or ".." in name:
        return True
    pure = PureWindowsPath(name)
    if pure.drive or pure.root:
        return True                      # ``C:``、``C:x``、``\\server\share``
    return len(pure.parts) != 1          # 必須剛好是一層


def _within_allowed_roots(path, roots) -> bool:
    """True iff `path` **解析後**落在 `roots` 其中一個底下（不含根目錄本身）。

    這是 `_is_unsafe_folder_name` 的**姊妹**，不是它的替代品，兩者的合法值形狀
    相反、不能互換：

    | 守衛 | 判準 | 合法值 |
    |---|---|---|
    | `_is_unsafe_folder_name` | 必須是**單一層**的相對元件 | ``columbina (genshin impact)`` |
    | `_within_allowed_roots`  | 解析後必須落在某個根底下 | ``output/_oneshot/<id>/x.png``、絕對路徑 |

    把單一元件那支套到多層／絕對路徑上，會把**每一個合法值都擋掉**；反過來把這支
    套到單一元件上則太鬆。用途決定形狀，不要「統一」成一支。

    ⚠️ **必須比對解析後的形式——這是這支函式最容易寫錯的一點。**
    `Path.parents` 是**純字彙**運算，它不知道 ``..`` 是什麼意思，所以字面版的
    ``root in p.parents`` 對一個逃出去的字串會**回 True**（本機 CPython 3.14.4
    實測）：

        OUTPUT_ROOT / "../../Windows/x.png"
          → 字面 parents 含 OUTPUT_ROOT           → True   ← 錯，而且無聲
          → .resolve() 得 D:\\Work\\Windows\\x.png → 不在底下 → False  ← 對

    根目錄自己也要 `resolve()`：``output/`` 可能是 junction／symlink，只解析一邊
    的話兩個字串永遠對不上，而症狀是**合法的路徑被默默拒絕**。

    `resolve()` 在本機這個版本上對 null byte／無效磁碟機其實**不會**丟例外（它對
    不存在的路徑是純字彙運算），但那是版本與平台的性質、不是契約，所以照樣接住
    `OSError`／`ValueError` 並 **fail-closed 回 False**。單一個壞掉的根只跳過那個
    根（`continue`），不連坐其他根——那仍然是對該根 fail-closed。

    根目錄自己不算「在底下」（用 `base in resolved.parents`，不是 `==`）：呼叫端要
    的都是「根底下的**檔案**」，把根本身放行沒有任何用途，只是多一個表面。
    """
    try:
        resolved = Path(path).resolve()
    except (OSError, ValueError):
        return False
    for root in roots:
        try:
            base = Path(root).resolve()
        except (OSError, ValueError):
            continue
        if base in resolved.parents:
            return True
    return False


# `_RECENT_IMAGE_MSGS` 裡的路徑允許落在哪些根底下。這份清單是從
# `_remember_image_msg` 的呼叫端反推出來的（2026-09-09 逐一複驗）：
#   `cmd_latest` / `cmd_latest_for` / `cmd_sample` / `cmd_fav_show` → `OUTPUT_ROOT`
#   `_dorossi_send_images`                                          → `CODEX_IMAGE_ROOT`
# ⚠️ **少列一個根不會噴錯**，只會讓那條路徑的合法對應在下次啟動時被默默丟掉，
# 使用者按 🗑️／⭐ 沒有反應也沒有訊息。新增一個會 `_remember_image_msg` 的表面時，
# 先問它的檔案寫在哪個根底下，再回來補這裡。
_IMAGE_MSG_ROOTS = (OUTPUT_ROOT, CODEX_IMAGE_ROOT)


async def cmd_debug_show(message: discord.Message, payload: str) -> None:
    name = payload.strip()
    # Path-traversal guard.
    if _is_unsafe_folder_name(name):
        await safe_reply(message, "invalid name")
        return
    # No argument → list available debug_*.png files (most recent first).
    if not name:
        try:
            shots = sorted(
                [
                    p for p in PROJECT_ROOT.iterdir()
                    if p.is_file()
                    and p.name.startswith("debug_")
                    and p.suffix.lower() == ".png"
                ],
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
        except OSError:
            shots = []
        if not shots:
            await safe_reply(message, "找不到任何除錯截圖")
            return
        rows = []
        for p in shots[:30]:
            when = time.strftime("%m-%d %H:%M:%S", time.localtime(p.stat().st_mtime))
            rows.append(f"  {p.name}  ({when})")
        more = f"\n… (+{len(shots) - 30} more)" if len(shots) > 30 else ""
        body = "\n".join(rows) + more
        await safe_reply(
            message,
            f"available debug screenshots ({len(shots)}):\n"
            f"```\n{_fence_escape(body)}\n```\n"
            f"usage: `/out debug_show <name>` — e.g. `/out debug_show after_setup`"
        )
        return
    # Auto-fix common shorthand: !debug_show after_setup → debug_after_setup.png
    candidate = name if name.startswith("debug_") else f"debug_{name}"
    if not candidate.lower().endswith(".png"):
        candidate = f"{candidate}.png"
    path = PROJECT_ROOT / candidate
    if not path.exists() or not path.is_file():
        await safe_reply(message, f"`{candidate}` not found")
        return
    size = path.stat().st_size
    limit = _upload_limit_bytes(message)
    if size > limit:
        await safe_reply(
            message,
            f"`{candidate}` is {size / 1024 / 1024:.1f} MB > "
            f"{_mb_text(limit)} upload limit"
        )
        return
    when = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(path.stat().st_mtime))
    await safe_reply(
        message, f"`{candidate}` ({size / 1024:.1f} KB, {when})",
        file=discord.File(str(path), filename=candidate))


_LIST_ALIASES: dict[str, Path] = {
    "prompt": TODO_PROMPT_FILE, "tp": TODO_PROMPT_FILE, "p": TODO_PROMPT_FILE,
    "char1": TODO_FILE_1, "c1": TODO_FILE_1, "1": TODO_FILE_1,
    "char2": TODO_FILE_2, "c2": TODO_FILE_2, "2": TODO_FILE_2,
    "negp": TODO_UNDESIRED_FILE, "tn": TODO_UNDESIRED_FILE,
    "undesired": TODO_UNDESIRED_FILE,
}


def _resolve_list(name: str) -> Path | None:
    return _LIST_ALIASES.get(name.lower())


def _shorten(text: str, limit: int = 300) -> str:
    if not text:
        return "(empty)"
    return text if len(text) <= limit else text[:limit] + "…"


async def cmd_preview(message: discord.Message) -> None:
    """Show the next triple webrunner would consume — mirrors webrunner's
    fallback rules so what you see is what'll run."""
    todo_p = read_todo_entries(TODO_PROMPT_FILE)
    todo_1 = read_todo_entries(TODO_FILE_1)
    todo_2 = read_todo_entries(TODO_FILE_2)
    if not (todo_p or todo_1 or todo_2 or _fallback_text(PROMPT_FILE)
            or _fallback_text(CHARACTER1_FILE)
            or _fallback_text(CHARACTER2_FILE)):
        # 真實佇列全空**且**連一個 fallback 都沒有內容才是真的沒東西可預覽。
        # 佇列空但有 fallback 時 webrunner 仍會產「剛好一個」fallback 角色
        # （`_queue_consume.ACTION_FALLBACK_SINGLE`），所以那要照常預覽出來。
        await safe_reply(message, "all queues empty — nothing to preview")
        return
    # If the next main prompt is the `end` stop-marker, the run halts here —
    # don't render it as a normal prompt.
    if todo_p and _is_end_marker(todo_p[0]):
        await safe_reply(
            message,
            "⏹ 主提示詞佇列下一筆是 `end` marker — the run "
            "would stop immediately (no pair generated). `/todo prompt unend` to resume."
        )
        return
    # prompt: todo_prompt head OR fallback to prompt.md
    if todo_p:
        prompt_head = todo_p[0]
        prompt_src = "主提示詞佇列[1]"
    else:
        # 這三個 fallback 讀取一律走 `_fallback_text`，不要自己重寫一次：那支
        # helper 接得住「檔案不是 UTF-8」並回空字串，所以同一個 Big5 的
        # `prompt.md`，`/gen plan` 與這裡的預覽會給出同一個答案（在那之前
        # 前者活得下來、後者留下裸 `UnicodeDecodeError`）。
        fb = _fallback_text(PROMPT_FILE)
        prompt_head = fb
        prompt_src = "主提示詞預設 (fallback)" if fb else "(none)"
    # char1: todo_character1 head OR fallback character1.md
    if todo_1:
        c1_head = todo_1[0]
        c1_src = "角色1 佇列[1]"
    else:
        fb = _fallback_text(CHARACTER1_FILE)
        c1_head = fb
        c1_src = "角色1 預設 (fallback)" if fb else "(none)"
    # char2: todo_character2 head OR fallback character2.md
    if todo_2:
        c2_head = todo_2[0]
        c2_src = "角色2 佇列[1]"
    else:
        fb = _fallback_text(CHARACTER2_FILE)
        c2_head = fb
        c2_src = "角色2 預設 (fallback)" if fb else "(none)"
    body = (
        f"main prompt  ← {prompt_src}\n"
        f"{_shorten(prompt_head)}\n\n"
        f"character 1  ← {c1_src}\n"
        f"{_shorten(c1_head)}\n\n"
        f"character 2  ← {c2_src}\n"
        f"{_shorten(c2_head)}"
    )
    safe = _fence_escape(body)
    await safe_reply(message, f"**next pair to be run:**\n```\n{safe}\n```")


def _fallback_text(path: Path) -> str:
    # `UnicodeDecodeError` 是 `ValueError` 的子類別、**不是** `OSError`，所以單寫
    # `except OSError` 接不住「檔案不是 UTF-8」。這四個 fallback 檔（`prompt.md`
    # / `character{1,2}.md` / `undesired.md`）是使用者手編的，被別的編輯器另存成
    # Big5 就會踩到；拋出去會讓 `/gen plan` 這類預覽整支爆掉。回空字串 ＝ 「這個
    # fallback 沒東西」，跟檔案不存在同一條路。
    # 刻意不加 `errors="replace"`：把亂碼當成有效提示詞送進佇列預覽，比「當作空的」
    # 糟得多——後者至少是已知且可預期的行為。
    try:
        return path.read_text(encoding="utf-8").strip() if path.exists() else ""
    except (OSError, UnicodeDecodeError):
        return ""


def _compute_run_plan() -> tuple[list[tuple[str, str, str, str]], dict]:
    """Mirror webrunner main()'s queue assembly: substitute fallbacks for any
    of the four empty queues, then zip the lists with last-entry padding.
    Returns (pairs, fallback_flags)."""
    p = read_todo_entries(TODO_PROMPT_FILE)
    c1 = read_todo_entries(TODO_FILE_1)
    c2 = read_todo_entries(TODO_FILE_2)
    u = read_todo_entries(TODO_UNDESIRED_FILE)
    fb = {"prompt": False, "char1": False, "char2": False, "undesired": False}
    if not p and (t := _fallback_text(PROMPT_FILE)):
        p, fb["prompt"] = [t], True
    if not c1 and (t := _fallback_text(CHARACTER1_FILE)):
        c1, fb["char1"] = [t], True
    if not c2 and (t := _fallback_text(CHARACTER2_FILE)):
        c2, fb["char2"] = [t], True
    if not u and (t := _fallback_text(UNDESIRED_FILE)):
        u, fb["undesired"] = [t], True
    # 配對改呼叫共用的 pair_todos（單一來源）：短清單重複最後一筆 padding、空清單
    # 變空字串、全空回 []，與舊 inline fill/zip 逐字等價（含全空 → ([], fb)）。
    pairs = _queue_consume.pair_todos(p, c1, c2, u)
    return pairs, fb


async def cmd_plan(message: discord.Message, payload: str) -> None:
    """Full run plan — exactly the pairs webrunner would walk on `/run`,
    after fallback substitution and `end`-marker truncation. `/gen plan [N]`
    caps the listed rows (default 25, max 60)."""
    arg = payload.strip()
    try:
        cap = int(arg) if arg else 25
    except ValueError:
        cap = 25
    cap = max(1, min(cap, 60))
    pairs, fb = _compute_run_plan()
    if not pairs:
        await safe_reply(message, "all queues empty (and no fallbacks) — nothing to run")
        return
    # `end` is located over ALL pairs, not inside the capped listing loop: with
    # the marker past the cap, a loop that stops at the cap never reaches it and
    # the header would count every pair after `end` as well.
    end_at = _end_marker_index([pair[0] for pair in pairs])
    stopped_at = end_at + 1 if end_at is not None else None
    effective = end_at if end_at is not None else len(pairs)
    rows: list[str] = []
    for i, (p, c1, c2, _u) in enumerate(pairs[:min(effective, cap)], 1):
        name = _plan_char_name(c1) if c1 else (
            _plan_char_name(c2) if c2 else "(no character)")
        rows.append(f"[{i}] {name}  ⟵ {_shorten(p, 46)}")
    body = "\n".join(rows) if rows else "(no pairs before the `end` marker)"
    if len(body) > 1700:
        body = body[:1700] + "\n… (truncated)"
    safe = _fence_escape(body)
    notes: list[str] = []
    used_fb = [k for k, v in fb.items() if v]
    if used_fb:
        notes.append("fallback used for: " + ", ".join(used_fb))
    if stopped_at is not None:
        notes.append(f"⏹ `end` marker at pair #{stopped_at} — stops there")
    if effective > len(rows):
        notes.append(f"showing {len(rows)} of {effective} pairs (`/gen plan {effective}` for more)")
    footer = ("\n" + " · ".join(notes)) if notes else ""
    await safe_reply(
        message,
        f"**run plan — {effective} pair(s) will run:**\n```\n{safe}\n```{footer}"
    )


async def cmd_move(message: discord.Message, payload: str) -> None:
    parts = payload.strip().split()
    if len(parts) != 3:
        await safe_reply(
            message,
            "usage: `/todo move <list> <i> <top|bottom>` "
            "— list: `prompt` / `char1` / `char2`"
        )
        return
    list_name, idx_str, where = parts
    path = _resolve_list(list_name)
    if not path:
        await safe_reply(message, f"unknown list `{list_name}` (prompt / char1 / char2)")
        return
    try:
        idx = int(idx_str)
    except ValueError:
        await safe_reply(message, "`i` must be an integer (1-based)")
        return
    where = where.lower()
    if where not in ("top", "bottom"):
        await safe_reply(message, "position must be `top` or `bottom`")
        return
    entries = read_todo_entries(path)
    if not entries:
        await safe_reply(message, f"**{_list_label(path, message)}** is empty")
        return
    if idx < 1 or idx > len(entries):
        await safe_reply(message, f"index out of range (1..{len(entries)})")
        return
    # 已經在那裡就不寫檔（同 `/todo swap` 的 i == j）：原樣寫回去的那一瞬間若批次剛好
    # 取走一筆，這次寫入會把它寫回來。
    if idx == (1 if where == "top" else len(entries)):
        await safe_reply(message, f"entry #{idx} is already at the {where}; nothing to do")
        return
    item = entries.pop(idx - 1)
    if where == "top":
        entries.insert(0, item)
    else:
        entries.append(item)
    write_todo_entries(path, entries)
    preview = _fence_preview(item, 100)
    await safe_reply(
        message,
        f"moved entry #{idx} → **{where}** of **{_list_label(path, message)}**\n```\n{preview}\n```"
    )


async def cmd_swap(message: discord.Message, payload: str) -> None:
    parts = payload.strip().split()
    if len(parts) != 3:
        await safe_reply(
            message,
            "usage: `/todo swap <list> <i> <j>` — list: `prompt` / `char1` / `char2`"
        )
        return
    list_name, i_str, j_str = parts
    path = _resolve_list(list_name)
    if not path:
        await safe_reply(message, f"unknown list `{list_name}`")
        return
    try:
        i, j = int(i_str), int(j_str)
    except ValueError:
        await safe_reply(message, "indices must be integers")
        return
    entries = read_todo_entries(path)
    if not entries:
        await safe_reply(message, f"**{_list_label(path, message)}** is empty")
        return
    n = len(entries)
    if not (1 <= i <= n and 1 <= j <= n):
        await safe_reply(message, f"indices out of range (1..{n})")
        return
    if i == j:
        await safe_reply(message, "i == j; nothing to do")
        return
    entries[i - 1], entries[j - 1] = entries[j - 1], entries[i - 1]
    write_todo_entries(path, entries)
    await safe_reply(message, f"swapped #{i} and #{j} in **{_list_label(path, message)}** ({n} entries)")


async def cmd_log_clear(message: discord.Message) -> None:
    # 這一支**刻意留在事件迴圈上**，跟 `/log tail|grep|errors|size` 丟執行緒不一樣
    # （2026-09-19）。那四支只讀；這一支會截斷 log、刪掉上一輪的 `.prev`，而
    # `_spawn_webrunner` 也在迴圈上對同兩個檔做「關 handle → 改名或複製成 `.prev` →
    # 截斷重開」。丟到執行緒，截斷就可能落在輪替的「改名失敗」與「複製」之間，
    # `.prev` 拿到的是一份空檔——崩潰證據在最需要的時候不見；在迴圈上兩者不可能交錯。
    # 下面那條 handle 路徑碰的是 `_webrunner_log_handle` 這個全域，本來就只能在迴圈上。
    # 成本是固定的（`stat`、`unlink`、截斷，不讀內容）。
    #
    # If the bot is the one holding the log file (webrunner running through
    # !run in this session), truncate via that handle so Windows file-lock
    # doesn't bite us.
    if _webrunner_log_handle and not _webrunner_log_handle.closed:
        try:
            _webrunner_log_handle.seek(0)
            _webrunner_log_handle.truncate()
            _discard_prev_log()
            await safe_reply(message, "已清空 log（透過使用中的 handle）")
            return
        except Exception as error:  # pylint: disable=broad-except
            print(f"truncate via handle failed: {error!r}", file=sys.stderr)
    if not WEBRUNNER_LOG.exists():
        await safe_reply(message, "log 檔尚不存在")
        return
    try:
        size = WEBRUNNER_LOG.stat().st_size + _discard_prev_log()
        WEBRUNNER_LOG.write_text("", encoding="utf-8")
    except OSError as error:
        print(f"cmd_log_clear failed: {error!r}", file=sys.stderr)
        await safe_reply(
            message,
            _owner_error(
                message, error, "清空 log 失敗（背景程式可能仍持有檔案 — 先 `/stop` 再試）")
        )
        return
    await safe_reply(
        message,
        f"已清空 log（釋出 {size / 1024:.1f} KB）"
    )


async def cmd_cleanup_debug(message: discord.Message) -> None:
    # **不要照原樣丟 `asyncio.to_thread`**（2026-09-19）。這裡走訪的是 repo 根目錄，
    # 而 bot 自己在迴圈上 `os.replace` 的檔幾乎全在那裡（四個佇列、暫停標記、pid、
    # 單張請求檔…）。`Path.is_file()` 是一次 `os.stat`，在 Windows 上會開一個 handle
    # ——本機實測一條執行緒不停 `iterdir()`＋`is_file()` 時，同目錄的 `os.replace`
    # 在兩個直譯器上分別是 7/3000 與 0/3000（機率性，但不是零）。真要搬走，先把走訪
    # 改成 `_dir_size` 那種 `os.scandir` 寫法（`entry.is_file()`／`entry.stat()` 讀的是
    # 目錄列舉帶回來的資料、不開檔，同一個量測兩邊都是 0/3000），並且先用檔名篩掉非
    # `debug_*.png` 的項目；判準見 `cmd_doctor` 開頭。根目錄約 77 項，同樣項數的合成
    # 目錄上整段走訪實測約 1.5 ms，留在迴圈上的代價很小。
    deleted = 0
    total_size = 0
    failed: list[str] = []
    try:
        entries = list(PROJECT_ROOT.iterdir())
    except OSError as error:
        print(f"cleanup_debug scan failed: {error!r}", file=sys.stderr)
        await safe_reply(message, _owner_error(
            message, error, "掃描失敗，請查看 log。"))
        return
    for p in entries:
        if not p.is_file():
            continue
        if not p.name.startswith("debug_") or p.suffix.lower() != ".png":
            continue
        try:
            size = p.stat().st_size
            p.unlink()
            deleted += 1
            total_size += size
        except OSError as error:
            failed.append(f"{p.name}: {error!r}")
    if deleted == 0 and not failed:
        await safe_reply(message, "沒有除錯截圖需要清理")
        return
    body = f"deleted {deleted} 張除錯截圖 ({total_size / 1024 / 1024:.2f} MB freed)"
    if failed:
        print("cleanup_debug failures: " + "; ".join(failed), file=sys.stderr)
        body += f"\n{len(failed)} 個刪除失敗（請查看 log）"
    await safe_reply(message, body)


# ---------- NovelAI ! commands (latest_for, sample, history, log_size,
#            disk, duplicate, shuffle, find) -----------------------------

async def cmd_latest_for(message: discord.Message, payload: str) -> None:
    name = payload.strip()
    if not name:
        await safe_reply(message, "usage: `/out latest_for <character folder>`")
        return
    # Path-traversal guard（與 cmd_debug_show 同）。Windows 上帶磁碟機的絕對
    # 路徑會**取代**整個 base：`OUTPUT_ROOT / "C:/Windows"` == `C:/Windows`。
    if _is_unsafe_folder_name(name):
        await safe_reply(message, "invalid name")
        return
    folder = OUTPUT_ROOT / name
    if not folder.is_dir():
        await safe_reply(message, f"folder `{name}/` not found")
        return
    images = []
    for p in folder.iterdir():
        if p.is_file() and p.suffix.lower() in (".png", ".jpg", ".jpeg", ".webp"):
            try:
                images.append((p.stat().st_mtime, p))
            except OSError:
                pass
    if not images:
        await safe_reply(message, f"`{name}/` has no images")
        return
    images.sort(key=lambda x: x[0], reverse=True)
    mtime, p = images[0]
    size = p.stat().st_size
    limit = _upload_limit_bytes(message)
    if size > limit:
        # Secrecy Layer 1：這條路徑**不會**上傳檔案，所以檔名只會出現在文字裡
        # ——那是主機上的命名慣例，沒有必要外流。大小是自己算的，可以講。
        await safe_reply(
            message,
            f"the newest one in `{name}/` is {size / 1024 / 1024:.1f} MB "
            f"> {_mb_text(limit)} cap"
        )
        return
    when = time.strftime("%H:%M:%S", time.localtime(mtime))
    sent = await safe_reply(
        message,
        # 檔名不寫進文字：附件本身就帶著檔名，重複一次只是多一個外流面。
        f"latest in `{name}/` ({when})",
        file=discord.File(str(p), filename=p.name))
    if sent is not None:
        _remember_image_msg(sent.id, [p])


def _split_trailing_count(payload: str, cap: int) -> tuple[str, int]:
    """把 `<名稱> [N]` 拆成 `(名稱, N)`；N 夾在 1..cap，沒給就是 1。

    只收 ASCII 數字：`isdigit()` 對上標數字（`²`）也是 True，`int()` 卻吃不下，
    於是整個指令變成一個例外。名稱可能是空字串（只給了數字）——呼叫端要把它當
    成「沒給名稱」，因為 `_is_unsafe_folder_name("")` 刻意放行空字串，
    `OUTPUT_ROOT / ""` 就是產出根目錄本身。
    """
    parts = payload.strip().split()
    if parts and parts[-1].isascii() and parts[-1].isdigit():
        return " ".join(parts[:-1]), max(1, min(int(parts[-1]), cap))
    return " ".join(parts), 1


async def cmd_sample(message: discord.Message, payload: str) -> None:
    name, n = _split_trailing_count(payload, 5)
    if not name:
        await safe_reply(message, "usage: `/out sample <character> [N]` (N max 5)")
        return
    if _is_unsafe_folder_name(name):
        await safe_reply(message, "invalid name")
        return
    folder = OUTPUT_ROOT / name
    if not folder.is_dir():
        await safe_reply(message, f"folder `{name}/` not found")
        return
    pool = [
        p for p in folder.iterdir()
        if p.is_file() and p.suffix.lower() in (".png", ".jpg", ".jpeg", ".webp")
    ]
    if not pool:
        await safe_reply(message, f"`{name}/` has no images")
        return
    picked = random.sample(pool, min(n, len(pool)))
    files = []
    paths_sent: list[Path] = []
    summary = []
    limit = _upload_limit_bytes(message)
    for p in picked:
        size = p.stat().st_size
        if size > limit:
            continue
        files.append(discord.File(str(p), filename=p.name))
        paths_sent.append(p)
        summary.append(f"`{p.name}`")
    if not files:
        await safe_reply(message, "all sampled images exceed the "
                                  f"{_mb_text(limit)} upload cap")
        return
    sent = await safe_reply(
        message, f"sample of `{name}/`: {', '.join(summary)}",
        files=files)
    if sent is not None:
        _remember_image_msg(sent.id, paths_sent)


async def cmd_history(message: discord.Message, payload: str) -> None:
    text = payload.strip()
    try:
        n = int(text) if text else 10
    except ValueError:
        await safe_reply(message, "usage: `/out history [N]`")
        return
    n = max(1, min(n, 30))
    images = _gather_output_images()
    if not images:
        await safe_reply(message, "no images yet")
        return
    images.sort(key=lambda x: x[0], reverse=True)
    rows = []
    for mtime, p in images[:n]:
        when = time.strftime("%m-%d %H:%M:%S", time.localtime(mtime))
        rows.append(f"{when}  {p.parent.name}/{p.name}")
    body = "\n".join(rows)
    if len(body) > 1700:
        body = body[:1700] + "\n…"
    await safe_reply(
        message,
        f"**history** — last {min(n, len(images))} of {len(images)}:\n"
        f"```\n{_fence_escape(body)}\n```"
    )


def _log_size_and_line_count() -> tuple[int, int] | None:
    """log 的 `(位元組數, 行數)`；還不存在回 None，存在卻讀不出來往外丟 `OSError`。

    數行數要把整份讀過一遍，所以 `/log size` 丟 `asyncio.to_thread` 跑；可以丟的理由
    見 `_webrunner_log_lines`。`stat` 也包在同一個 `try` 裡：原本它在 `try` 外面，
    輪替正好把檔案改名走的那一瞬間會讓 `FileNotFoundError` 一路逃到派發層。
    """
    try:
        size = WEBRUNNER_LOG.stat().st_size
        with WEBRUNNER_LOG.open("r", encoding="utf-8", errors="replace") as f:
            lines = sum(1 for _ in f)
    except FileNotFoundError:
        return None
    return size, lines


async def cmd_log_size(message: discord.Message) -> None:
    try:
        counted = await asyncio.to_thread(_log_size_and_line_count)
    except OSError as error:
        print(f"cmd_log_size read failed: {error!r}", file=sys.stderr)
        await safe_reply(message, _owner_error(
            message, error, "讀取 log 失敗，請查看主機 log。"))
        return
    if counted is None:
        await safe_reply(message, "log 檔尚不存在")
        return
    size, lines = counted
    await safe_reply(
        message,
        f"**log**: {size / 1024 / 1024:.2f} MB, {lines:,} lines"
    )


def _dir_size(path: Path) -> int:
    """`path` 底下所有檔案的位元組數總和（只算檔案），以 `os.scandir` 自己走訪。

    **不要改回 `Path.rglob` ＋ `p.is_file()` ＋ `p.stat()`**（2026-09-19 換掉的）。那個
    寫法在 Windows 上對**每一個檔**都做一次 `os.stat`，而那是一個真的 handle：走訪
    期間，同目錄裡別人的 `os.replace` 會失敗。這兩棵樹裡正好有別人在做原子寫入——
    產圖批次把登入狀態同步回瀏覽器設定檔時用 `os.replace`（單檔與整個目錄的兩段式
    改名都有）、瀏覽器自己也是。本機實測，一條執行緒不停走訪、主執行緒在同目錄
    `os.replace` 3000 次：舊寫法 4/3000 與 7/3000（兩個直譯器），`os.scandir` 的
    `entry.is_file()`／`entry.stat()` 兩邊都是 0/3000——非符號連結的項目，它讀的是
    目錄列舉帶回來的資料，不開檔。也就是說，`/sys health`、`/sys disk` 原本會讓批次的
    登入狀態同步失敗。

    語意跟舊的 `rglob("*")` 對齊（3.14 的實作讀過原始碼、在本機並排比過）：
    * 只在 `entry.is_dir(follow_symlinks=False)` 為真時往下走——junction 會走進去、
      指向目錄的符號連結不會（`rglob` 預設 `recurse_symlinks=False` 用的正是這個判斷）；
    * 指向檔案的符號連結算目標的大小（`is_file()`／`stat()` 預設跟隨連結，跟
      `Path.is_file()`／`Path.stat()` 一樣），壞掉的連結不算；
    * 讀不到的目錄與單一項目的 `OSError` 一律略過，不中斷整趟走訪。

    代價（尺寸報告可以接受）：**別人正開著寫的檔，目錄項裡的大小會落後**——NTFS
    不是每次寫入都更新目錄項，關檔時才一定更新。實測一個開著的檔寫到 4,000,000
    位元組時，列舉仍報 1,000,000、`os.stat` 報 4,000,000；關檔之後兩者一致。所以正在
    被寫的 log、資料庫檔可能偏小。
    """
    total = 0
    stack = [os.fspath(path)]
    while stack:
        current = stack.pop()
        try:
            with os.scandir(current) as scan:
                entries = list(scan)
        except OSError:
            continue
        for entry in entries:
            try:
                if entry.is_dir(follow_symlinks=False):
                    stack.append(entry.path)
                elif entry.is_file():
                    total += entry.stat().st_size
            except OSError:
                pass
    return total


def _disk_usage_rows() -> list[str]:
    """`/sys disk` 表格的每一列。整段是目錄遞迴走訪，要在工作執行緒上跑。

    2026-09-19 以前整段跑在事件迴圈上，而同樣兩棵樹的走訪在 `/sys health` 那邊實測約
    18 ms＋30 ms（快取熱）。丟執行緒的理由跟 `_health_disk_bits` 一樣（寫在那支的
    docstring）：bot 不會在這兩棵樹裡做 `os.replace`——產出資料夾是背景程式寫的、
    設定檔是瀏覽器寫的——所以沒有「執行緒裡的讀者擋住同一個行程在迴圈上的存檔」那個
    問題。bot 自己換的檔全部在 repo 根目錄，不在這兩棵樹裡。

    別的行程在這兩棵樹裡的原子寫入（批次同步登入狀態、瀏覽器自己）原本也有曝險：
    舊的 `_dir_size` 對每個檔開一個 handle。同日已把 `_dir_size` 改成 `os.scandir`
    走訪、不開檔（量測與語意見那支的 docstring），那個曝險跟著消失——它跟在迴圈上或
    執行緒上走訪無關，所以是在那一支修，不是在這裡。
    """
    targets = {
        "產出資料夾": OUTPUT_ROOT,
        "瀏覽器設定檔": CHROME_PROFILE_DIR,
    }
    rows = []
    grand = 0
    for label, path in targets.items():
        if not path.exists():
            rows.append(f"  {label:<20}  (missing)")
            continue
        size = _dir_size(path)
        grand += size
        rows.append(f"  {label:<20}  {size / 1024 / 1024:>9.2f} MB")
    rows.append(f"  {'TOTAL':<20}  {grand / 1024 / 1024:>9.2f} MB")
    return rows


async def cmd_disk(message: discord.Message) -> None:
    rows = await asyncio.to_thread(_disk_usage_rows)
    await safe_reply(message, "**disk usage**\n```\n" + "\n".join(rows) + "\n```")


async def cmd_duplicate(message: discord.Message, payload: str) -> None:
    parts = payload.strip().split()
    if len(parts) < 2:
        await safe_reply(
            message,
            "usage: `/todo duplicate <list> <i> [n]` (default n=1)"
        )
        return
    list_name = parts[0]
    try:
        idx = int(parts[1])
        n = int(parts[2]) if len(parts) > 2 else 1
    except ValueError:
        await safe_reply(message, "indices / count must be integers")
        return
    if n < 1 or n > 50:
        await safe_reply(message, "n must be 1-50")
        return
    path = _resolve_list(list_name)
    if not path:
        await safe_reply(message, f"unknown list `{list_name}`")
        return
    entries = read_todo_entries(path)
    if not entries:
        await safe_reply(message, f"**{_list_label(path, message)}** is empty")
        return
    if idx < 1 or idx > len(entries):
        await safe_reply(message, f"index out of range (1..{len(entries)})")
        return
    item = entries[idx - 1]
    for _ in range(n):
        entries.insert(idx, item)
    write_todo_entries(path, entries)
    await safe_reply(
        message,
        f"duplicated entry #{idx} of **{_list_label(path, message)}** ×{n} "
        f"({len(entries)} total)"
    )


async def cmd_shuffle(message: discord.Message, payload: str) -> None:
    list_name = payload.strip()
    if not list_name:
        await safe_reply(message, "usage: `/todo shuffle <list>`")
        return
    path = _resolve_list(list_name)
    if not path:
        await safe_reply(message, f"unknown list `{list_name}`")
        return
    entries = read_todo_entries(path)
    if len(entries) < 2:
        await safe_reply(message, f"**{_list_label(path, message)}** has < 2 entries; nothing to shuffle")
        return
    random.shuffle(entries)
    write_todo_entries(path, entries)
    # 洗牌保留空白列的「數量」，但會改變它們落在第幾對。角色2 佇列的空白列是
    # 「這一對不要 Character 2」的位置標記，所以要講一聲——不擋，使用者本來就是
    # 要打亂順序，只是別讓標記位移變成意外。
    blanks = sum(1 for e in entries if not e.strip())
    note = (f"；其中 {blanks} 列空白（「不要 Character 2」的位置標記）也一起"
            f"換了位置" if blanks and path == TODO_FILE_2 else "")
    await safe_reply(
        message,
        f"shuffled **{_list_label(path, message)}** ({len(entries)} entries){note}")


async def cmd_find(message: discord.Message, payload: str) -> None:
    parts = payload.strip().split(None, 1)
    if len(parts) < 2:
        await safe_reply(message, "usage: `/todo find <list> <substring>`")
        return
    list_name, needle = parts
    path = _resolve_list(list_name)
    if not path:
        await safe_reply(message, f"unknown list `{list_name}`")
        return
    entries = read_todo_entries(path)
    matches = [
        (i, e) for i, e in enumerate(entries, 1)
        if needle.lower() in e.lower()
    ]
    if not matches:
        await safe_reply(message, f"no entries in **{_list_label(path, message)}** match `{needle!r}`")
        return
    rows = [f"  [{i}] {e[:120]}{'…' if len(e) > 120 else ''}" for i, e in matches]
    body = "\n".join(rows)
    if len(body) > 1700:
        body = body[:1700] + "\n…"
    await safe_reply(
        message,
        f"**{_list_label(path, message)}** — {len(matches)} matches for `{needle!r}`:\n"
        f"```\n{_fence_escape(body)}\n```"
    )


async def cmd_dedupe(message: discord.Message, payload: str) -> None:
    """Remove duplicate entries from a todo list, keeping the FIRST occurrence
    of each (order preserved). Comparison is case-insensitive on the stripped
    text so `Lappland` and `lappland ` collapse. `end` markers are compared
    like any other entry (multiple `end`s collapse to one).

    **角色2 佇列帶有空白列時一律拒絕。** `todo_character2.md` 是位置式的
    （見 CLAUDE.md → todo file format）：第 N 列配第 N 對，空白列代表「這一對
    不要 Character 2」。去重是**整批刪列**，刪掉任何一列都會讓後面每一列往前
    位移，而空白列彼此的 key 都是 ""、會被當成重複而只留第一個——使用者刻意留
    的停用標記就這樣消失，後面每一對都配到錯的角色。這個錯誤不會當場報錯，要
    等幾小時後看產出資料夾才發現，所以寧可擋下來叫使用者用 `/todo remove`
    逐列處理。沒有空白列＝沒有在用位置語意，照常去重。"""
    list_name = payload.strip()
    if not list_name:
        await safe_reply(
            message,
            "usage: `/todo dedupe <list>` — list: `prompt` / `char1` / `char2` / `negp`"
        )
        return
    path = _resolve_list(list_name)
    if not path:
        await safe_reply(message, f"unknown list `{list_name}` (prompt / char1 / char2 / negp)")
        return
    entries = read_todo_entries(path)
    blanks = sum(1 for e in entries if not e.strip())
    if blanks and path == TODO_FILE_2:
        await safe_reply(
            message,
            f"**{_list_label(path, message)}** 有 {blanks} 列空白列——那是「這一對"
            f"不要 Character 2」的位置標記，不是重複項。去重會把它們刪掉並讓後面"
            f"每一列往前位移，之後每一對都會配到錯的角色，因此這裡不做去重。"
            f"要刪特定列請用 `/todo remove`。"
        )
        return
    seen: set[str] = set()
    kept: list[str] = []
    for e in entries:
        key = e.strip().lower()
        if key in seen:
            continue
        seen.add(key)
        kept.append(e)
    removed = len(entries) - len(kept)
    if removed == 0:
        await safe_reply(message, f"no duplicates in **{_list_label(path, message)}** ({len(entries)} entries)")
        return
    write_todo_entries(path, kept)
    plural = "duplicate" if removed == 1 else "duplicates"
    await safe_reply(
        message,
        f"removed {removed} {plural} from **{_list_label(path, message)}** "
        f"({len(entries)} → {len(kept)} entries)"
    )


async def cmd_output_stats(message: discord.Message) -> None:
    if not OUTPUT_ROOT.exists():
        await safe_reply(message, "產出資料夾還不存在 — 目前沒有任何圖片")
        return
    dirs = sorted([d for d in OUTPUT_ROOT.iterdir() if d.is_dir()])
    if not dirs:
        await safe_reply(message, "產出資料夾裡還沒有任何角色資料夾")
        return
    rows: list[str] = []
    total = 0
    for d in dirs:
        try:
            count = sum(
                1 for p in d.iterdir()
                if p.is_file() and p.suffix.lower() in (".png", ".jpg", ".jpeg", ".webp")
            )
        except OSError:
            count = 0
        total += count
        name = d.name if len(d.name) <= 48 else d.name[:45] + "…"
        rows.append(f"{name:<48}  {count:>5}")
    body = "\n".join(rows)
    if len(body) > 1700:
        body = body[:1700] + "\n… (truncated)"
    await safe_reply(
        message,
        f"**產出統計** — {len(dirs)} folders, {total} images total\n"
        f"```\n{_fence_escape(body)}\n```"
    )


async def cmd_rate(message: discord.Message) -> None:
    """Throughput stats from output-image mtimes: how many landed in the last
    1h / 6h / 24h, the average images/hour over the active window, and the
    age of the newest image (a stalled run shows a large 'last image' gap)."""
    images = _gather_output_images()
    if not images:
        await safe_reply(message, "no images yet")
        return
    now = time.time()
    mtimes = sorted(t for t, _ in images)
    def _since(secs: float) -> int:
        cutoff = now - secs
        return sum(1 for t in mtimes if t >= cutoff)
    last_1h = _since(3600)
    last_6h = _since(6 * 3600)
    last_24h = _since(24 * 3600)
    newest = mtimes[-1]
    gap = now - newest
    # Honest images/hour: count of images within the last 24h divided by the
    # span they actually cover (oldest-recent → now), not a fixed 24h window —
    # so a run only 2h old isn't diluted by 22h of "idle" it was never up for.
    recent = [t for t in mtimes if t >= now - 24 * 3600]
    span_s = max(now - min(recent), 60.0) if recent else 1.0
    rate = len(recent) / (span_s / 3600)
    # 「沒有新圖」有三種，只有第三種是異常。前兩種都是**可預期的閒置**，而這一
    # 行原本對它們一律亮紅字。先問清楚是哪一種再決定要不要警告；順序不可顛倒。
    # 兩個判斷共用同一份事件（省掉第二次讀檔，也免得兩者看到不同的快照）。
    events = _read_events_tail()
    resting_until = _scheduled_rest_until(events)
    quota_retry_at = _quota_wait_until(events)
    if resting_until is not None:
        stall = ("  💤 on a scheduled rest until "
                 f"{time.strftime('%H:%M', time.localtime(resting_until))}")
    elif quota_retry_at is not None:
        # 等額度回補：`quota_wait_poll_sec` 預設就是 3600，跟下面那個門檻同一個
        # 數字，所以**每一個**額度週期都會讓它亮。實測 15.7% 的時刻在謊報。
        stall = "  ⏸️ waiting for quota to refill"
        if quota_retry_at > now:
            stall += (", next retry "
                      f"{time.strftime('%H:%M', time.localtime(quota_retry_at))}")
    elif gap > 3600:
        stall = "  ⚠️ no new image in over an hour"
    else:
        stall = ""
    embed = discord.Embed(title="📈 generation rate", color=0x5865F2)
    embed.add_field(name="last 1h", value=f"`{last_1h}`", inline=True)
    embed.add_field(name="last 6h", value=f"`{last_6h}`", inline=True)
    embed.add_field(name="last 24h", value=f"`{last_24h}`", inline=True)
    embed.add_field(
        name="avg images/hour",
        value=f"`{rate:.1f}` (over {_format_duration_short(span_s)})",
        inline=True,
    )
    embed.add_field(name="total images", value=f"`{len(images)}`", inline=True)
    embed.add_field(
        name="newest image",
        value=f"`{_format_duration_short(gap)} ago`{stall}",
        inline=True,
    )
    await safe_reply(message, embed=embed)


# `/booru <tag>` 支援的 modifier flags（POSIX 風格）。`--` 不會跟 booru
# tag 撞（Danbooru tag 不含這個字元組合），可以安全嵌在 tag 字串裡。
# 接受的同義詞：`--newest` == `--latest`。未知 flag 不報錯、直接當 tag 處理
# 比較寬鬆，但 strict path 也行（這裡留寬鬆，反正錯 tag 也找不到圖）。
_DANBOORU_FLAG_TOKENS = frozenset({"latest", "newest", "grid"})


def _parse_danbooru_flags(text: str) -> tuple[set[str], str]:
    """從 tag string 拆出 `--<flag>` token，回 (flags_set, remaining_tags)。

    Flags: `--latest` / `--newest`（同義）、`--grid`。其他不在白名單裡的
    `--xxx` token 不當 flag、保留進 tag string（雖然 Danbooru 大概也找不
    到，但至少不會 silent ignore 看起來像 typo 的東西）。"""
    tokens = text.split()
    flags: set[str] = set()
    rest_tokens: list[str] = []
    for t in tokens:
        if t.startswith("--") and len(t) > 2:
            name = t[2:].lower()
            if name in _DANBOORU_FLAG_TOKENS:
                # `--newest` 視為 `--latest` 的同義詞
                flags.add("latest" if name == "newest" else name)
                continue
        rest_tokens.append(t)
    return flags, " ".join(rest_tokens)


def _normalise_tag_input(text: str) -> str:
    r"""Make a human tag string Danbooru-friendly. Booru tags use underscores
    inside a single tag (e.g. `rossi_(arknights)`) and spaces between tags.
    A common pattern from copy/paste is `rossi (arknights)` — a single tag
    written with a space. Heuristic: a whitespace-`(` sequence collapses to
    `_(`. 必須是 `\s+\(`（至少一個空白），否則本來就是 canonical 的
    `rossi_(arknights)` 會被多塞一個底線變成 `rossi__(arknights)`。"""
    s = text.strip()
    # lookbehind：只從一段空白的開頭起跑，否則一長串空白每個起點都掃到底。上一筆比對一定
    # 停在非空白上（`\(\s*` 把後面的空白吃完、`\)` 本身不是空白），所以結果不變。
    s = re.sub(r"(?<!\s)\s+\(\s*", "_(", s)
    s = re.sub(r"(?<!\s)\s+\)", ")", s)
    return s


async def _send_danbooru_image(message: discord.Message, tags: str) -> None:
    """`/booru <tag(s)> [--latest] [--grid]` 統一入口。解析 flag 後 dispatch
    到對應的 single / grid handler。詳細邏輯見 `_send_danbooru_single` /
    `_send_danbooru_grid`。"""
    flags, clean_tags = _parse_danbooru_flags(tags)
    if not clean_tags.strip():
        # 純 flag、沒給 tag → 用 `@bot`（無參數）的同一個預設值。
        clean_tags = "rossi_(arknights)"
    want_latest = "latest" in flags
    want_grid = "grid" in flags
    if want_grid:
        await _send_danbooru_grid(message, clean_tags, latest=want_latest)
    else:
        await _send_danbooru_single(message, clean_tags, latest=want_latest)


async def _send_danbooru_single(
    message: discord.Message, tags: str, *, latest: bool = False
) -> None:
    """Fetch + reply with one Danbooru post for `tags`. `latest=False` →
    random（既有預設行為），`latest=True` → 最新一張。

    Tag 字串自動補 `rating:general` 如果沒指定 rating。0 posts 時走
    `_resolve_fuzzy_tags` 透過 `/tags.json` 把模糊輸入轉成 canonical tag
    再試一次；轉換成功會在回覆裡顯示 `🔍 解析 X → Y`。"""
    original = tags
    tags_with_rating = (
        tags if "rating:" in tags else f"{tags} rating:general".strip()
    )
    fetcher = _fetch_danbooru_post_latest if latest else _fetch_danbooru_post
    post = await fetcher(tags_with_rating)
    resolved: str | None = None
    if not post:
        # Resolver 吃使用者原始 tag string（不含自動補的 rating），免得把
        # `rating:general` 拆進 window。
        candidate = await _resolve_fuzzy_tags(_DANBOORU_TAGS, original)
        if candidate and candidate != original:
            resolved = candidate
            retry_tags = (
                candidate if "rating:" in candidate
                else f"{candidate} rating:general"
            )
            post = await fetcher(retry_tags)
        if not post:
            shown = resolved or tags_with_rating
            await safe_reply(message, f"找不到符合 `{shown}` 的圖片")
            return
    url = (
        post.get("file_url")
        or post.get("large_file_url")
        or post.get("preview_file_url")
    )
    pid = post.get("id")
    page = f"https://danbooru.donmai.us/posts/{pid}" if pid is not None else None
    if not url:
        await safe_reply(
            message,
            f"post {pid} has no fetchable image URL{f' — {page}' if page else ''}"
        )
        return
    parts = []
    if resolved:
        parts.append(f"🔍 解析 `{original}` → `{resolved}`")
    if latest:
        parts.append(f"📅 最新（post #{pid}）" if pid is not None else "📅 最新")
    if page:
        parts.append(f"<{page}>")
    parts.append(url)
    await safe_reply(message, "\n".join(parts))


def _format_duration(seconds: float) -> str:
    s = int(seconds)
    days, s = divmod(s, 86400)
    hours, s = divmod(s, 3600)
    minutes, s = divmod(s, 60)
    parts = []
    if days:
        parts.append(f"{days}d")
    if hours:
        parts.append(f"{hours}h")
    if minutes:
        parts.append(f"{minutes}m")
    parts.append(f"{s}s")
    return " ".join(parts)




def _roll_dice(spec: str) -> str | None:
    """Parse 'NdM' (e.g. '2d6'); return a rolled summary or None on bad spec."""
    spec = spec.strip().lower() or "1d6"
    match = re.fullmatch(r"(\d{1,3})d(\d{1,4})", spec)
    if not match:
        return None
    n, sides = int(match.group(1)), int(match.group(2))
    if n < 1 or sides < 2 or n > 100 or sides > 1000:
        return None
    rolls = [random.randint(1, sides) for _ in range(n)]
    total = sum(rolls)
    if n == 1:
        return f"🎲 1d{sides} → **{total}**"
    return f"🎲 {n}d{sides} → {rolls} = **{total}**"


