async def mcmd_rand(message: discord.Message, rest: str) -> None:
    parts = rest.split()
    if len(parts) != 2:
        await safe_reply(message, "usage: `/fun rand <min> <max>`")
        return
    try:
        lo, hi = int(parts[0]), int(parts[1])
    except ValueError:
        await safe_reply(message, "min / max must be integers")
        return
    if lo > hi:
        lo, hi = hi, lo
    await safe_reply(message, f"🎲 {random.randint(lo, hi)} (range {lo}..{hi})")


async def mcmd_coinflip(message: discord.Message) -> None:
    await safe_reply(message, f"🪙 **{random.choice(('heads', 'tails'))}**")


_RPS_NORM = {"r": "rock", "rock": "rock", "p": "paper", "paper": "paper",
             "s": "scissors", "scissors": "scissors"}
_RPS_BEATS = {"rock": "scissors", "paper": "rock", "scissors": "paper"}


async def mcmd_rps(message: discord.Message, rest: str) -> None:
    user = _RPS_NORM.get(rest.strip().lower())
    if not user:
        await safe_reply(message, "usage: `/fun rps <rock|paper|scissors>` (also `r`/`p`/`s`)")
        return
    bot = random.choice(("rock", "paper", "scissors"))
    if user == bot:
        outcome = "draw"
    elif _RPS_BEATS[user] == bot:
        outcome = "you win"
    else:
        outcome = "you lose"
    await safe_reply(message, f"you: **{user}** vs bot: **{bot}** → **{outcome}**")


async def mcmd_reverse(message: discord.Message, rest: str) -> None:
    if not rest:
        await safe_reply(message, "usage: `/fun reverse <text>`")
        return
    await safe_reply(message, rest[::-1])


async def mcmd_ascii(message: discord.Message, rest: str) -> None:
    if pyfiglet is None:
        await safe_reply(message, "ASCII art 功能未安裝相依套件，暫時無法使用。")
        return
    if not rest:
        await safe_reply(message, "usage: `/fun ascii <text>`")
        return
    try:
        art = pyfiglet.figlet_format(rest[:60])
    except Exception as error:  # pylint: disable=broad-except
        print(f"ascii render failed: {error!r}", file=sys.stderr)
        await safe_reply(message, _owner_error(
            message, error, "ascii render failed"))
        return
    if len(art) > 1900:
        art = art[:1900] + "…"
    safe = _fence_escape(art)
    await safe_reply(message, f"```\n{safe}\n```")


# At most six digits: anything longer is over 24 hours anyway, and an unbounded `\d+`
# makes `int()` raise past 4300 digits (CPython's int-string limit).
_TIMER_RE = re.compile(r"^([0-9]{1,6})\s*([smh]?)\s*(.*)$", re.IGNORECASE | re.DOTALL)
# Per-person cap on pending timers. The command is public (no channel or role gate), and
# every timer is a task sleeping up to 24 hours that posts when it fires — uncapped, one
# person could queue tens of thousands and use up the bot's send budget within a day.
TIMER_MAX_PENDING_PER_USER = 10
_timers_pending: dict[int, int] = {}


async def mcmd_timer(message: discord.Message, rest: str) -> None:
    """`/fun timer <Ns|Nm|Nh> [message]`: pings the caller in the same channel when it fires.

    Timers live only in this process's memory (a restart drops them); at most
    `TIMER_MAX_PENDING_PER_USER` per person, released when one fires (or fails to send)."""
    m = _TIMER_RE.match(rest.strip())
    if not m:
        await safe_reply(message, "usage: `/fun timer <Ns|Nm|Nh> <message>`")
        return
    value = int(m.group(1))
    unit = (m.group(2) or "s").lower()
    msg = m.group(3).strip() or "(time's up)"
    seconds = {"s": 1, "m": 60, "h": 3600}[unit] * value
    if seconds < 1 or seconds > 24 * 3600:
        await safe_reply(message, "duration must be between 1s and 24h")
        return
    author = message.author
    owner_key = getattr(author, "id", None)
    if _timers_pending.get(owner_key, 0) >= TIMER_MAX_PENDING_PER_USER:
        await safe_reply(
            message,
            f"you already have {TIMER_MAX_PENDING_PER_USER} timers running — "
            "wait for one to finish first")
        return
    _timers_pending[owner_key] = _timers_pending.get(owner_key, 0) + 1
    await safe_reply(
        message,
        f"⏰ will ping you in {_format_duration(seconds)} — `{msg[:200]}`"
    )

    channel = message.channel

    async def _fire():
        try:
            await asyncio.sleep(seconds)
            await channel.send(f"⏰ {author.mention} timer: {msg[:1500]}",
                               allowed_mentions=_mentions_for(author))
        except Exception as error:  # pylint: disable=broad-except
            print(f"timer fire failed: {error!r}", file=sys.stderr)
        finally:
            left = _timers_pending.get(owner_key, 1) - 1
            if left > 0:
                _timers_pending[owner_key] = left
            else:
                _timers_pending.pop(owner_key, None)

    _schedule_coro(_fire(), label="timer")


async def mcmd_calc(message: discord.Message, rest: str) -> None:
    if _simple_eval is None:
        await safe_reply(message, "`simpleeval` not installed on this bot")
        return
    if not rest.strip():
        await safe_reply(message, "usage: `/fun calc <expression>`  e.g. `/fun calc 2+2*3`")
        return
    # Defence-in-depth on this public (cross-channel) surface: cap input length
    # before eval. simpleeval guards string-multiply (MAX_STRING_LENGTH), compound
    # types and imports; its own ** limit only bounds the operands, not the result,
    # which is why `CALC_MAX_POWER` lowers it (see the import block). This cap
    # bounds parse cost and how many terms one expression can chain.
    if len(rest) > 500:
        await safe_reply(message, "calc error: `expression too long (max 500 chars)`")
        return
    try:
        result = _simple_eval(rest)
    except Exception as error:  # pylint: disable=broad-except
        print(f"calc error: {error!r}", file=sys.stderr)
        await safe_reply(message, f"calc error: `{type(error).__name__}`")
        return
    await safe_reply(message, _calc_result_line(result))


def _calc_result_line(result) -> str:
    """The `/fun calc` reply. A too-long result is not forced through: an integer over 4300
    digits makes even `str()` raise (CPython's int-string limit), which used to turn the whole
    command into a generic error."""
    try:
        shown = f"{result}"
    except ValueError:
        shown = None
    if isinstance(result, int) and not isinstance(result, bool) and (
            shown is None or len(shown) > 1800):
        digits = int(abs(result).bit_length() * 0.30102999566398) + 1
        return f"= a number with about {digits:,} digits (too long to show)"
    if shown is None:
        return "calc error: `result cannot be shown`"
    if len(shown) > 1800:
        return f"= **{shown[:1800]}…**"
    return f"= **{shown}**"


# ---------- @-mention: free APIs -------------------------------------------

def _api_contact_hint(status: int) -> str:
    """403／429 且聯絡方式未設定時的補充說明，否則空字串。

    **只給擁有者看**——呼叫端必須把它包在 `_owner_detail` 裡（它提到設定檔名，
    而 `*_config.json` 是 Layer 1 明文禁止送給其他人的形狀之一）。

    程式刻意不替擁有者挑一個聯絡方式：那個字串會被送到第三方站台，等於對外公布一
    個聯絡管道，是擁有者的決定。這裡能做的只有「講清楚要動哪個鍵」。
    """
    if status not in (403, 429) or _external_apis.contact_configured():
        return ""
    return ("\n（`api_contact` 尚未設定。有些站台要求 User-Agent 裡帶得到人的"
            "聯絡方式——URL 或 email——只自報名稱會被擋。在 bot_config.json 設好"
            "這個鍵即可；要放什麼上去是你的決定，程式不會替你挑。）")


def _json_dict(value) -> dict:
    """One level of external JSON: an object comes back as-is; anything else (null, a list,
    a string, a number) becomes an empty object.

    A website's response shape is not ours to control: on errors, rate limits or a redesign
    the same field turns into null or another type. The `/web` handlers used to `.get(...)`
    every level directly, so the first non-object turned the whole command into one generic
    error (fed malformed shapes one by one, 6 of 12 handlers raised)."""
    return value if isinstance(value, dict) else {}


def _json_list(value) -> list:
    """Same as `_json_dict`, for lists."""
    return value if isinstance(value, list) else []


def _json_text(value, default: str = "") -> str:
    """The value if it is a string, otherwise `default`."""
    return value if isinstance(value, str) else default


def _json_count(value) -> int | None:
    """The value if it is an int (bool excluded), otherwise None. For numbers formatted
    with `:,` — formatting a string or None that way raises."""
    return value if isinstance(value, int) and not isinstance(value, bool) else None


async def mcmd_wiki(message: discord.Message, rest: str) -> None:
    topic = rest.strip()
    if not topic:
        await safe_reply(message, "usage: `/web wiki <topic>`")
        return
    title = urllib.parse.quote(topic.replace(" ", "_"))
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{title}"
    status, data = await _http_get_json(url)
    if status != 200 or not data:
        # 403／429 而且聯絡方式沒設定，幾乎一定是同一件事：有些站台要求
        # User-Agent 裡帶得到人的聯絡方式（URL 或 email），只自報名稱會被擋。
        # 光看狀態碼查不出來，而可行動的那一行原本只進 stderr——擁有者在對話裡
        # 看到的永遠只有一個數字。
        #
        # 補充只給擁有者（`_owner_detail`）：它會提到設定檔，而設定檔名屬於
        # Layer 1 禁止送給其他人的那一類。非擁有者維持原本的泛用句。
        generic = f"wiki lookup failed (HTTP {status})"
        await safe_reply(message, _owner_detail(
            message, lambda: generic + _api_contact_hint(status), generic))
        return
    data = _json_dict(data)
    extract = _json_text(data.get("extract")).strip()
    page_url = _json_text(_json_dict(_json_dict(data.get("content_urls")).get("desktop")).get("page"))
    if not extract:
        await safe_reply(message, "no summary available")
        return
    if len(extract) > 1500:
        extract = extract[:1500] + "…"
    parts = [f"**{_json_text(data.get('title'), topic)}** — {extract}"]
    if page_url:
        parts.append(f"<{page_url}>")
    await safe_reply(message, "\n".join(parts))


# `/web dict` 專用的逾時。`_external_apis._HTTP_TIMEOUT_SEC` 是 15 秒，而這個端點
# 2026-09-08 實測**穩定要 20 秒左右**（連打五次：19.9／20.1／0.4／19.9／20.1）——
# 也就是說這個指令在此之前**每一次都失敗**，而且失敗訊息是 `not found`，看起來像
# 是那個字不存在。查證過不是我們這一側的問題：同一個網址帶專案的 UA 回 HTTP 200，
# 只是慢；帶 Python 預設 UA 則被 Cloudflare 0.4 秒內 403（所以「換個 UA 試試」會
# 得到相反的結論）。
# **只放寬這一個呼叫，不要動 `_HTTP_TIMEOUT_SEC` 的預設值**：那個預設套用在每一個
# 外部呼叫上，調大等於讓所有真的掛掉的站台都多吊使用者好幾秒。
DICT_TIMEOUT_SEC = 30.0


async def mcmd_dict(message: discord.Message, rest: str) -> None:
    word = rest.strip()
    if not word:
        await safe_reply(message, "usage: `/web dict <word>`")
        return
    url = f"https://api.dictionaryapi.dev/api/v2/entries/en/{urllib.parse.quote(word)}"
    status, data = await _http_get_json(url, timeout=DICT_TIMEOUT_SEC)
    if status == -1:
        # 逾時／連不上**不是**「查無此字」。2026-09-08 之前這裡把兩者收成同一句
        # `not found`，於是這個指令對每一個字都回「查無此字」——而那個端點其實是
        # 好的，只是慢。錯的答案比沒有答案糟：使用者會相信那個字不存在。
        await safe_reply(message, "字典查詢逾時了，請稍後再試。")
        return
    # **只有 404 可以說「查無此字」**（2026-09-19）。原本任何非 200 都回 `not found`，
    # 而當天實測字典服務的源站掛了：前面的快取層對沒快取過的字等約 20 秒回 HTTP 522，
    # 快取過的字回一份 53 天前的舊 200——也就是**大部分的字都被告知不存在**。跟上面
    # 逾時那一支同一個錯：把「查不成」講成「查到了，沒有」。5xx／522／429 與其他
    # 讀不懂的回應都是「查不成」；細節（狀態碼、網址）`_http_get_json` 已經寫進
    # stderr，這裡只回泛用句，不點名服務。
    if status == 404:
        await safe_reply(message, f"`{word}` not found")
        return
    if status != 200 or not isinstance(data, list):
        if status == 200:
            print(f"mcmd_dict: unexpected response shape "
                  f"({type(data).__name__})", file=sys.stderr)
        await safe_reply(message, "字典服務暫時無法使用，請稍後再試。")
        return
    if not data:
        # 服務有回答、而且回答是空的：這才是「沒有這個字」。
        await safe_reply(message, f"`{word}` not found")
        return
    entry = _json_dict(data[0])
    rows = [f"**{_json_text(entry.get('word'), word)}**"]
    for meaning in _json_list(entry.get("meanings"))[:3]:
        meaning = _json_dict(meaning)
        pos = _json_text(meaning.get("partOfSpeech"), "?")
        defs = _json_list(meaning.get("definitions"))
        d = _json_text(_json_dict(defs[0]).get("definition")) if defs else ""
        if not d:
            continue
        rows.append(f"_{pos}_: {d}")
    if len(rows) == 1:
        await safe_reply(message, "no definitions in response")
        return
    body = "\n".join(rows)
    if len(body) > 1800:
        body = body[:1800] + "…"
    await safe_reply(message, body)


async def mcmd_xkcd(message: discord.Message, rest: str) -> None:
    text = rest.strip()
    if text:
        try:
            num = int(text)
        except ValueError:
            await safe_reply(message, "usage: `/web xkcd [N]`")
            return
        url = f"https://xkcd.com/{num}/info.0.json"
    else:
        status, latest = await _http_get_json("https://xkcd.com/info.0.json")
        newest = _json_count(_json_dict(latest).get("num"))
        if status != 200 or not newest or newest < 1:
            await safe_reply(message, "could not reach xkcd")
            return
        num = random.randint(1, newest)
        url = f"https://xkcd.com/{num}/info.0.json"
    status, data = await _http_get_json(url)
    data = _json_dict(data)
    if status != 200 or not data:
        await safe_reply(message, f"xkcd #{num} fetch failed")
        return
    title = _json_text(data.get("title"), "(no title)")
    img = _json_text(data.get("img"))
    alt = _json_text(data.get("alt"))
    num_actual = _json_count(data.get("num")) or num
    embed = discord.Embed(
        title=f"xkcd #{num_actual}: {title}",
        description=alt,
        color=0x96A8C8,
        url=f"https://xkcd.com/{num_actual}/",
    )
    if img:
        embed.set_image(url=img)
    await safe_reply(message, embed=embed)


