# `/web anime` 那一次 GraphQL POST 的逾時。有名字是為了**對帳**：外部端點的驗證腳本
# （`verify_external_apis.py`）那一筆必須照抄同一個值，由
# `test_external_apis.test_a_per_call_timeout_in_the_bot_is_mirrored_here` 比對。
# 驗證腳本比 bot 寬，會在 bot 逾時的時候報 ok；比 bot 窄，會在 bot 好好的時候報
# 連不上——兩個方向都錯，所以數字只寫在這裡一次。
ANIME_TIMEOUT_SEC = 15.0


async def mcmd_anime(message: discord.Message, rest: str) -> None:
    title = rest.strip()
    if not title:
        await safe_reply(message, "usage: `/web anime <name>`")
        return
    query = """
    query ($search: String) {
      Media(search: $search, type: ANIME) {
        id title { romaji english } episodes averageScore status seasonYear
        siteUrl description(asHtml: false)
      }
    }
    """
    status, payload = await _http_post_json(
        "https://graphql.anilist.co",
        {"query": query, "variables": {"search": title}},
        timeout=ANIME_TIMEOUT_SEC)
    if status != 200 or not isinstance(payload, dict):
        # 細節（狀態碼、例外）已由 `_http_post_json` 寫進 stderr。
        await safe_reply(message, "anime 查詢失敗，請稍後再試。")
        return
    # 回應是外部資料：每一層都可能不是物件（錯誤時 `data` 是 null、欄位可能是 null）。
    data = payload.get("data")
    media = data.get("Media") if isinstance(data, dict) else None
    if not isinstance(media, dict):
        await safe_reply(message, f"no anime matching `{title}`")
        return
    t = media.get("title")
    t = t if isinstance(t, dict) else {}
    name = t.get("english") or t.get("romaji") or title
    desc = media.get("description")
    desc = desc.replace("<br>", "").strip() if isinstance(desc, str) else ""
    if len(desc) > 600:
        desc = desc[:600] + "…"
    embed = discord.Embed(
        title=name,
        description=desc,
        url=media.get("siteUrl") if isinstance(media.get("siteUrl"), str) else None,
        color=0x02A9FF,
    )
    embed.add_field(name="year", value=str(media.get("seasonYear", "?")), inline=True)
    embed.add_field(name="episodes", value=str(media.get("episodes", "?")), inline=True)
    embed.add_field(
        name="avg score",
        value=f"{media.get('averageScore', '?')}/100",
        inline=True,
    )
    embed.add_field(name="status", value=str(media.get("status", "?")), inline=True)
    await safe_reply(message, embed=embed)


async def mcmd_github(message: discord.Message, rest: str) -> None:
    repo = rest.strip()
    if "/" not in repo:
        await safe_reply(message, "usage: `/web github <user>/<repo>`")
        return
    status, data = await _http_get_json(
        f"https://api.github.com/repos/{urllib.parse.quote(repo)}"
    )
    data = _json_dict(data)
    if status != 200 or not data:
        await safe_reply(message, f"github lookup failed (HTTP {status})")
        return

    def _count(key: str) -> str:
        value = _json_count(data.get(key))
        return "?" if value is None else f"{value:,}"

    embed = discord.Embed(
        title=_json_text(data.get("full_name"), "?"),
        description=_json_text(data.get("description")) or "_(no description)_",
        url=_json_text(data.get("html_url")) or None,
        color=0x24292E,
    )
    embed.add_field(name="⭐ stars", value=_count("stargazers_count"), inline=True)
    embed.add_field(name="🍴 forks", value=_count("forks_count"), inline=True)
    embed.add_field(name="💬 issues", value=_count("open_issues_count"), inline=True)
    embed.add_field(name="🧰 language", value=_json_text(data.get("language")) or "?", inline=True)
    avatar = _json_text(_json_dict(data.get("owner")).get("avatar_url"))
    if avatar:
        embed.set_thumbnail(url=avatar)
    await safe_reply(message, embed=embed)


async def mcmd_crypto(message: discord.Message, rest: str) -> None:
    sym = rest.strip().lower()
    if not sym:
        await safe_reply(message, "usage: `/web crypto <symbol>` (e.g. `btc`, `eth`)")
        return
    # Resolve symbol → coingecko id via search.
    status, search = await _http_get_json(
        "https://api.coingecko.com/api/v3/search", params={"query": sym}
    )
    if status != 200 or not search:
        await safe_reply(message, f"crypto 查詢失敗 (HTTP {status})")
        return
    coins = _json_list(_json_dict(search).get("coins"))
    coin = _json_dict(coins[0]) if coins else {}
    coin_id = _json_text(coin.get("id"))
    if not coin_id:
        await safe_reply(message, f"no coin matching `{sym}`")
        return
    status, price = await _http_get_json(
        "https://api.coingecko.com/api/v3/simple/price",
        params={"ids": coin_id, "vs_currencies": "usd,twd"},
    )
    p = _json_dict(_json_dict(price).get(coin_id))
    if status != 200 or not p:
        await safe_reply(message, f"price fetch failed for `{coin_id}`")
        return

    def _price(key: str) -> str:
        value = p.get(key)
        return (str(value) if isinstance(value, (int, float)) and not isinstance(value, bool)
                else "?")

    await safe_reply(
        message,
        f"**{_json_text(coin.get('name'), coin_id)}** ({_json_text(coin.get('symbol')).upper()}) — "
        f"${_price('usd')} USD / NT${_price('twd')}"
    )


