@discord.app_commands.describe(
    when="排程：`in 90m` / `in 2h` / `at 02:00` / `cancel`；"
         "也可寫 `label <名稱>` 先命名這一批")
async def slash_run(interaction: discord.Interaction, when: str = "") -> None:
    # `when` 維持單一字串：`label <名稱>` 會與 `in`／`at` 組合（
    # `_extract_run_label` 先剝標籤、`_parse_run_schedule` 再看其餘），拆成三個
    # 互相牽制的可選參數只會更難用也更難驗。parser 仍是唯一來源。
    await _slash_run(interaction, cmd_run, when)


