@discord.app_commands.describe(
    prompt="主提示詞", character1="角色 1（可省略）",
    character2="角色 2（可省略）", negative="負面提示詞（可省略）")
async def slash_gen_image(interaction: discord.Interaction, prompt: str,
                          character1: str = "", character2: str = "",
                          negative: str = "") -> None:
    # mcmd_generate 吃 `<主提示> | <角色1> | <角色2> | <負面>`。四個具名選項比
    # 一條要自己數分隔線的字串好用，組回去的成本只有這一行。
    payload = " | ".join([prompt, character1, character2, negative]).rstrip(" |")
    await _slash_run(interaction, mcmd_generate, payload,
                     detach_ack="🎨 已收下，排入產圖佇列…")


