input_group = discord.app_commands.Group(
    name="input", description="鍵盤與滑鼠輸入（限擁有者）")

_BUTTON_CHOICES = [
    discord.app_commands.Choice(name="左鍵", value="left"),
    discord.app_commands.Choice(name="右鍵", value="right"),
    discord.app_commands.Choice(name="中鍵", value="middle"),
]


@input_group.command(name="click", description="在指定座標按一下",
                     extras={"bang": "!click"})
@discord.app_commands.describe(
    x="X 座標", y="Y 座標", button="要按哪個鍵",
    window="改用相對此視窗左上角的座標（視窗一移動絕對座標就全錯）",
    background="送給背景視窗、不搶焦點（盡力而為）",
    shot="完成後附一張截圖")
@discord.app_commands.choices(button=_BUTTON_CHOICES)
async def slash_input_click(
        interaction: discord.Interaction,
        x: discord.app_commands.Range[int, -65535, 65535],
        y: discord.app_commands.Range[int, -65535, 65535],
        button: str = "left", window: str = "",
        background: bool = False, shot: bool = False) -> None:
    payload = f"{x} {y} {button}"
    if shot:
        payload += " --shot"
    if background:
        payload += " --bg"
    # `--win` 必須留在最後：`_take_trailing_option` 把它之後的整段當值，
    # 因為視窗標題片段常常帶空白。
    if window:
        payload += f" --win {window}"
    await _slash_run(interaction, cmd_click, payload)


