locate_group = discord.app_commands.Group(
    name="locate", description="用文字 / 圖片 / 元素名稱在畫面上定位（限擁有者）")

locate_text = discord.app_commands.Group(
    name="text", description="用畫面文字定位（需辨識引擎）", parent=locate_group)
locate_image = discord.app_commands.Group(
    name="image", description="用樣板圖片定位（不需辨識引擎）",
    parent=locate_group)
locate_ui = discord.app_commands.Group(
    name="ui", description="用元素名稱定位（首選：問作業系統要精確矩形）",
    parent=locate_group)


@locate_text.command(name="find", description="找文字並回座標與信心值",
                     extras={"bang": "!find_text"})
@discord.app_commands.describe(text="要找的文字", region="限定區域「x y 寬 高」",
                               lang="辨識語言代碼（留空 = 自動判斷）")
async def slash_locate_text_find(interaction: discord.Interaction, text: str,
                                 region: str = "", lang: str = "") -> None:
    payload = ""
    if region:
        payload += f"--in {region} "
    if lang:
        payload += f"--lang {lang} "
    await _slash_run(interaction, cmd_find_text, payload + text,
                     detach_ack="⏳ 辨識中…")


@locate_text.command(name="click", description="找到畫面上的文字就點下去",
                     extras={"bang": "!click_text"})
@discord.app_commands.describe(text="要點的文字", lang="辨識語言代碼",
                               shot="完成後附一張截圖")
async def slash_locate_text_click(interaction: discord.Interaction, text: str,
                                  lang: str = "", shot: bool = False) -> None:
    payload = ""
    if lang:
        payload += f"--lang {lang} "
    if shot:
        payload += "--shot "
    await _slash_run(interaction, cmd_click_text, payload + text,
                     detach_ack="⏳ 辨識中…")


@locate_text.command(name="wait", description="等某段文字出現在畫面上",
                     extras={"bang": "!wait_text"})
@discord.app_commands.describe(text="要等的文字", seconds="最長等幾秒",
                               lang="辨識語言代碼")
async def slash_locate_text_wait(
        interaction: discord.Interaction, text: str,
        seconds: discord.app_commands.Range[int, 1, 600] = 30,
        lang: str = "") -> None:
    payload = f"{seconds} "
    if lang:
        payload += f"--lang {lang} "
