# ---------- 巨集：/macro ----------------------------------------------------
macro_group = discord.app_commands.Group(
    name="macro", description="巨集（限擁有者）：存 / 錄 / 跑 / 編輯")


@macro_group.command(name="save", description="存一份巨集",
                     extras={"bang": "!macro"})
@discord.app_commands.describe(
    name="巨集名稱",
    steps="步驟，用 `;` 分隔一步（選項輸入框打不出換行）",
    file="或者直接附一個檔案，一行一步（比 `;` 好寫得多）")
async def slash_macro_save(interaction: discord.Interaction, name: str,
                           steps: str = "",
                           file: discord.Attachment = None) -> None:
    # 選項輸入框沒辦法打換行，而巨集本體是一行一步的迷你語言。所以提供兩條
    # 路：`;` 分隔（短巨集夠用），或直接附檔（長巨集的實際寫法）。隱藏的
    # `/macro save` 仍然是最順手的撰寫介面，help 會直說。
    if file is not None:
        try:
            body = (await file.read()).decode("utf-8", "replace")
        except Exception as error:  # pylint: disable=broad-except
            print(f"/macro save attachment read failed: {error!r}",
                  file=sys.stderr)
            await _slash_reply_generic(interaction, "附件讀取失敗。")
            return
    else:
        body = steps.replace(";", "\n")
    await _slash_run(interaction, cmd_macro, f"save {name}\n{body}")


