@tool_group.command(name="say", description="讓 bot 代為發言（限 server owner）",
                    extras={"public": True})
@discord.app_commands.describe(text="要讓 bot 說的內容")
async def slash_tool_say(interaction: discord.Interaction, text: str) -> None:
    # mcmd_say 的成功路徑走 channel.send（不是 reply），deferred interaction
    # 不會被 followup 完成而永遠掛在「思考中…」。用 ephemeral defer：拒絕/
    # usage 回覆（走 proxy.reply → followup）只有本人看得到；成功時 proxy 的
    # finish() 補一個 ack 把 interaction 收尾，實際發言仍由 mcmd_say 公開送出。
    await interaction.response.defer(thinking=True, ephemeral=True)
    await _slash_run(interaction, mcmd_say, text)


