info_group = discord.app_commands.Group(
    name="info", description="頭貼 / server / channel 資訊")


@info_group.command(name="avatar", description="顯示頭貼（預設自己）",
                    extras={"public": True})
@discord.app_commands.describe(user="要查頭貼的使用者（可省略）")
async def slash_info_avatar(interaction: discord.Interaction,
                            user: discord.User | None = None) -> None:
    # mcmd_avatar 從 message.mentions 取目標；slash 沒有 mentions，把 user
    # option 塞進 proxy.mentions 重用同一個 handler。_tree_check 已經把 proxy
    # 放進 interaction.extras，所以要改的是**那一個**，不是新建一個。
    proxy = interaction.extras.get("proxy") or _InteractionMessageProxy(interaction)
    if user is not None:
        proxy.mentions = [user]
    interaction.extras["proxy"] = proxy
    await _slash_run(interaction, mcmd_avatar, "")


